22	/// `Path::canonicalize`, with a path that does not exist as `None`. Any other failure (a permission error, a loop) is an
23	/// error: reading it as "no such directory" would drop a dependency edge unseen.
24	fn canonical_if_present(path: &Path) -> std::io::Result<Option<PathBuf>> {
25	    match path.canonicalize() {
26	        Ok(canonical) => Ok(Some(canonical)),
27	        Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(None),
28	        Err(error) => Err(error),
29	    }
30	}
