32	/// The npm package a relative `workspace:../path` dependency of `declaring_manifest` names, or `None` when the path
33	/// leaves the workspace, does not exist, or holds no admitted npm package.
34	fn relative_workspace_package<'a>(
35	    root: &Path,
36	    declaring_manifest: &Path,
37	    relative: &str,
38	    mut packages: impl Iterator<Item = &'a Package>,
39	) -> std::io::Result<Option<PackageId>> {
40	    let root = root.canonicalize()?;
41	    let Some(source) = root
42	        .join(declaring_manifest)
43	        .parent()
44	        .map(canonical_if_present)
45	        .transpose()?
46	        .flatten()
47	    else {
48	        return Ok(None);
49	    };
50	    let Some(target) = canonical_if_present(&source.join(relative))? else {
51	        return Ok(None);
52	    };
53	    if !target.starts_with(&root) {
54	        return Ok(None);
55	    }
56	    for package in packages.by_ref() {
57	        for manifest in package.canonical_manifests() {
58	            if manifest.ecosystem() != Ecosystem::Npm {
59	                continue;
60	            }
61	            let dir = root.join(manifest.path.parent().unwrap_or(Path::new("")));
62	            if canonical_if_present(&dir)?.as_ref() == Some(&target) {
63	                return Ok(Some(package.id.clone()));
64	            }
65	        }
66	    }
67	    Ok(None)
68	}
