88	/// Disjointness test for two paths' name-scoped claiming-ecosystem sets --
89	/// {Cargo,Npm} and {Npm} are unequal but not disjoint. Kept for the
90	/// `is_promoted_bare_name` unit tests below; actual duplicate detection is
91	/// `native_owner` in `build`, keyed by every declared (ecosystem, name), not
92	/// just each path's primary name.
93	#[cfg(test)]
94	fn claiming_sets_disjoint(a: &BTreeSet<Ecosystem>, b: &BTreeSet<Ecosystem>) -> bool {
95	    a.is_disjoint(b)
96	}
