141	impl ManifestWalkResolver {
142	    pub fn build<L: ProjectLocator, R: CommandRunner>(
143	        root: &Path,
144	        locator: &L,
145	        _runner: &R,
146	        cfg: &ResolvedConfig,
147	        manifest_cache: &RefCell<BTreeMap<PathBuf, Arc<dyn Manifest>>>,
148	    ) -> Result<Self, GraphError> {
149	        let ctx = OpenContext::for_workspace_root(root)?;
150	        let mut diagnostics = Vec::new();
151	
152	        let discovered = discover(root, locator, manifest_cache, &ctx, &mut diagnostics)?;
153	        let Identified {
154	            package_manifest_decls,
