222	fn assign_identities(
223	    discovered: Discovered,
224	    manifest_cache: &RefCell<BTreeMap<PathBuf, Arc<dyn Manifest>>>,
225	    ctx: &OpenContext<'_>,
226	) -> Result<Identified, GraphError> {
227	    let Discovered {
228	        by_path,
229	        attached_platforms,
230	    } = discovered;
231	    let mut assigner = IdentityAssigner::new(manifest_cache, ctx);
232	    for (rel_path, list) in by_path {
233	        if attached_platforms.contains_key(&rel_path) {
234	            continue;
235	        }
236	        assigner.assign(rel_path, list)?;
237	    }
238	    assigner.attach_platforms(attached_platforms);
239	    Ok(assigner.finish())
240	}
