518	        let current_set = self.claiming_ecosystems.get(&rel_path).cloned().unwrap_or_default();
519	        self.promoted_siblings
520	            .entry(name.clone())
521	            .or_default()
522	            .extend([(existing_id, existing_set), (current_id, current_set)]);
523	    }
