526	    fn attach_platforms(&mut self, attached_platforms: BTreeMap<PathBuf, (PathBuf, String, ManifestRole)>) {
527	        for (platform_dir, (owner_dir, name, role)) in attached_platforms {
528	            let manifest_rel = platform_dir.join("package.json");
529	            let owner = self.package_manifest_decls.iter_mut().find(|(_, (path, decls))| {
530	                *path == owner_dir && decls.iter().any(|d| d.format == ManifestFormat::PackageJson)
531	            });
532	            let Some((owner_id, (_, decls))) = owner else {
533	                self.unresolved.push(unresolved(
534	                    &manifest_rel,
535	                    "attach it to its owner",
536	                    format!("`{}` has no npm manifest to own it", owner_dir.display()),
537	                ));
538	                continue;
539	            };
540	            match ManifestDecl::new(manifest_rel.clone(), role.clone(), ManifestFormat::PackageJson) {
541	                Ok(decl) => {
542	                    decls.push(decl);
543	                    self.index.platform.insert(name, (owner_id.clone(), manifest_rel, role));
544	                }
545	                Err(error) => self
546	                    .unresolved
547	                    .push(unresolved(&manifest_rel, "declare its platform manifest", error)),
548	            }
