561	/// Opens the canonical manifests that `resolve_packages` is about to open one at a time, on several threads: opening
562	/// reads and parses the file, which is independent per manifest. One that fails to open is opened again below, which
563	/// reports it.
564	fn prewarm_manifests(
565	    package_manifest_decls: &BTreeMap<PackageId, (PathBuf, Vec<ManifestDecl>)>,
566	    manifest_cache: &RefCell<BTreeMap<PathBuf, Arc<dyn Manifest>>>,
567	    ctx: &OpenContext<'_>,
568	) {
569	    let wanted: Vec<&ManifestDecl> = package_manifest_decls
570	        .values()
571	        .flat_map(|(_, decls)| decls.iter())
572	        .filter(|decl| decl.role == ManifestRole::Canonical && !manifest_cache.borrow().contains_key(&decl.path))
573	        .collect();
574	    let opened = map_in_parallel(&wanted, |decl| callisto_manifests::open(decl, ctx));
575	    let mut cache = manifest_cache.borrow_mut();
576	    for (decl, opened) in wanted.into_iter().zip(opened) {
577	        if let Ok(manifest) = opened {
578	            cache.insert(decl.path.clone(), Arc::from(manifest));
579	        }
580	    }
581	}
