789	/// One edge per dependency declaration of each canonical manifest that resolves to a workspace package.
790	fn build_edges(
791	    root: &Path,
792	    packages: &BTreeMap<PackageId, Package>,
793	    index: &IdentityIndex,
794	    manifest_cache: &RefCell<BTreeMap<PathBuf, Arc<dyn Manifest>>>,
795	    ctx: &OpenContext<'_>,
796	    diagnostics: &mut Vec<Diagnostic>,
797	) -> (Vec<DepEdge>, EdgeIndex, EdgeIndex) {
798	    let mut edges = Vec::new();
799	    let mut out_index: BTreeMap<PackageId, Vec<usize>> = BTreeMap::new();
800	    let mut in_index: BTreeMap<PackageId, Vec<usize>> = BTreeMap::new();
801	
802	    for pkg in packages.values() {
803	        for decl in &pkg.manifests {
804	            if decl.role != ManifestRole::Canonical {
805	                continue;
806	            }
807	            let m = match open_cached(manifest_cache, decl, ctx) {
808	                Ok(m) => m,
809	                Err(error) => {
810	                    diagnostics.push(unresolved(
811	                        &decl.path,
812	                        "open its manifest to read its dependencies",
813	                        error,
814	                    ));
815	                    continue;
816	                }
817	            };
818	            {
819	                for entry in m.iter_dependencies() {
820	                    let inherited = entry.inherited.then(|| m.inherited_dependency(&entry.name)).flatten();
821	                    let (spec, declaring_path) = match inherited {
822	                        Some(dep) => (dep.spec.clone(), dep.declared_in.to_path_buf()),
823	                        None => (entry.spec.clone(), decl.path.clone()),
824	                    };
825	
826	                    let workspace_target = match &spec {
827	                        DepSpec::WorkspaceProtocol(workspace) => workspace.relative_path().and_then(|relative| {
828	                            relative_workspace_package(root, &decl.path, relative, packages.values()).unwrap_or_else(
829	                                |error| {
830	                                    diagnostics.push(unresolved(
831	                                        &decl.path,
832	                                        "resolve a relative `workspace:` dependency",
833	                                        error,
834	                                    ));
835	                                    None
836	                                },
837	                            )
838	                        }),
839	                        _ => None,
840	                    };
841	                    let diagnostics_before = diagnostics.len();
842	                    let to = match &spec {
843	                        DepSpec::WorkspaceProtocol(workspace) if workspace.relative_path().is_some() => {
844	                            workspace_target
845	                        }
846	                        _ => workspace_target.or_else(|| {
847	                            index
848	                                .resolve_native_with_fallback(decl.ecosystem(), &entry.package_name, diagnostics)
849	                                .cloned()
850	                        }),
851	                    };
852	                    if let Some(to) = to {
853	                        let idx = edges.len();
854	                        let edge = DepEdge {
855	                            from: pkg.id.clone(),
856	                            to: to.clone(),
857	                            name: entry.name,
858	                            kind: entry.kind,
859	                            spec,
860	                            from_manifest: declaring_path,
861	                            inherited: entry.inherited,
862	                            locator: entry.locator,
863	                        };
864	                        edges.push(edge);
865	
866	                        out_index.entry(pkg.id.clone()).or_default().push(idx);
867	                        in_index.entry(to).or_default().push(idx);
868	                    } else if let DepSpec::WorkspaceProtocol(workspace) = &spec {
869	                        let relative = workspace.relative_path().is_some();
870	                        // A cross-ecosystem name miss already warned; one warning per reference.
871	                        if relative || diagnostics.len() == diagnostics_before {
872	                            let form = if relative { "relative " } else { "" };
873	                            diagnostics.push(Diagnostic {
874	                                code: DiagnosticCode::UnknownPackage,
875	                                severity: DiagnosticSeverity::Warning,
876	                                message: format!(
877	                                    "{form}pnpm workspace dependency `{}` from `{}` does not identify an admitted npm workspace member",
878	                                    entry.name,
879	                                    decl.path.display()
880	                                ),
881	                                package: Some(pkg.id.clone()),
882	                                path: Some(decl.path.clone()),
883	                                escalated_by: None,
884	                                governed_by: None,
885	                            });
886	                        }
887	                    }
888	                }
889	            }
890	        }
891	    }
892	
893	    (edges, out_index, in_index)
894	}
