896	/// Maps each npm-only platform package directory (`os`+`cpu`)
897	/// to the owner directory whose `package.json` names it in `optionalDependencies`,
898	/// plus the platform's own name and role. `non_members` are platform packages
899	/// outside the npm workspace, attachable but otherwise not discovered. A member
900	/// platform named by no owner, or by more than one, stays its own package with a
901	/// diagnostic.
902	fn platform_owners(
903	    root: &Path,
904	    by_path: &BTreeMap<PathBuf, Vec<(Ecosystem, PackageId)>>,
905	    non_members: &[callisto_model::ProjectRoot],
906	    manifest_cache: &RefCell<BTreeMap<PathBuf, Arc<dyn Manifest>>>,
907	    ctx: &OpenContext<'_>,
908	    diagnostics: &mut Vec<Diagnostic>,
909	) -> BTreeMap<PathBuf, (PathBuf, String, ManifestRole)> {
910	    let open_npm = |rel_path: &Path| -> Result<Arc<dyn Manifest>, Diagnostic> {
911	        let manifest_rel = rel_path.join("package.json");
912	        let decl = ManifestDecl::new(
913	            manifest_rel.clone(),
914	            ManifestRole::Canonical,
915	            ManifestFormat::PackageJson,
916	        )
917	        .map_err(|error| unresolved(&manifest_rel, "declare its manifest", error))?;
918	        open_cached(manifest_cache, &decl, ctx)
919	            .map_err(|error| unresolved(&manifest_rel, "open its manifest to read its platform role", error))
920	    };
921	    let platform_role = |manifest: &Arc<dyn Manifest>| match manifest.npm_role()? {
922	        callisto_manifests::NpmRole::Platform { platform, arch, abi } => {
923	            Some(ManifestRole::Platform { platform, arch, abi })
924	        }
925	    };
926	
927	    let mut platforms = Vec::new();
928	    let mut owners_of: BTreeMap<String, Vec<PathBuf>> = BTreeMap::new();
929	    for (rel_path, list) in by_path {
930	        let Some((_, id)) = list.iter().find(|(eco, _)| *eco == Ecosystem::Npm) else {
931	            continue;
932	        };
933	        let manifest = match open_npm(rel_path) {
934	            Ok(manifest) => manifest,
935	            Err(problem) => {
936	                diagnostics.push(problem);
937	                continue;
938	            }
939	        };
940	        // A co-located platform manifest already belongs to its directory's package.
941	        match platform_role(&manifest) {
942	            Some(role) if list.len() == 1 => platforms.push((rel_path.clone(), id.name().to_string(), role, true)),
943	            _ => {
944	                for dep in manifest.iter_dependencies() {
945	                    if dep.kind == callisto_model::DepKind::Optional {
946	                        owners_of.entry(dep.name).or_default().push(rel_path.clone());
947	                    }
948	                }
949	            }
950	        }
951	    }
952	    for candidate in non_members {
953	        if by_path.contains_key(&candidate.path) {
954	            continue;
955	        }
956	        // A Cargo/Python package physically sits beside this candidate's package.json even
957	        // though it wasn't discovered as a workspace member here (e.g. filtered out by that
958	        // ecosystem's own membership) -- attaching it as a bare platform manifest would
959	        // misattach a directory that already hosts a real, distinct package.
960	        let beside = |name: &str| callisto_model::strict_fs::exists(&root.join(&candidate.path).join(name));
961	        match (beside("Cargo.toml"), beside("pyproject.toml")) {
962	            (Ok(false), Ok(false)) => {}
963	            (Err(error), _) | (_, Err(error)) => {
964	                diagnostics.push(unresolved(
965	                    &candidate.path,
966	                    "check whether another package shares its directory",
967	                    error,
968	                ));
969	                continue;
970	            }
971	            _ => continue,
972	        }
973	        let role = match open_npm(&candidate.path) {
974	            Ok(manifest) => platform_role(&manifest),
975	            Err(problem) => {
976	                diagnostics.push(problem);
977	                None
978	            }
979	        };
980	        if let Some(role) = role {
981	            platforms.push((candidate.path.clone(), candidate.id.name().to_string(), role, false));
982	        }
983	    }
984	
985	    let mut attached = BTreeMap::new();
986	    for (rel_path, name, role, member) in platforms {
987	        match owners_of.get(&name).map(Vec::as_slice) {
988	            Some([owner]) => {
989	                attached.insert(rel_path, (owner.clone(), name, role));
990	            }
991	            None if !member => {}
992	            owners => {
993	                let reason = match owners {
994	                    Some(owners) => format!(
995	                        "is named in the optionalDependencies of {} packages ({})",
996	                        owners.len(),
997	                        owners
998	                            .iter()
999	                            .map(|p| p.display().to_string())
1000	                            .collect::<Vec<_>>()
1001	                            .join(", ")
1002	                    ),
1003	                    None => "is not named in any npm package's optionalDependencies".to_string(),
1004	                };
1005	                diagnostics.push(Diagnostic {
1006	                    code: DiagnosticCode::PlatformPackageWithoutOwner,
1007	                    severity: DiagnosticSeverity::Warning,
1008	                    message: format!(
1009	                        "npm platform package `{name}` {reason}; {}",
1010	                        if member {
1011	                            "it is released as its own package instead of as a platform manifest of its owner"
1012	                        } else {
1013	                            "it is outside the npm workspace, so it is not released at all"
1014	                        }
1015	                    ),
1016	                    package: None,
1017	                    path: Some(rel_path.join("package.json")),
1018	                    escalated_by: None,
1019	                    governed_by: None,
1020	                });
1021	            }
1022	        }
1023	    }
1024	    attached
1025	}
