19:     // Label for the report only; each package's actual version is built in its own grammar below.
20:     let snapshot_tag = format!("0.0.0-{tag}-{sha_short}");
21:     let base_versions = ws.base_versions()?;
22:     // No severity cascade to seed here; `ws.tags()` only checks the propagate-failure invariant below.
