25: /// and, for each, writes to stdout either:
26: ///
27: /// ```text
28: /// <sha> SP <type> SP <size> LF
29: /// <content: exactly `size` bytes> LF
30: /// ```
31: ///
32: /// or, if the object doesn't exist:
33: ///
34: /// ```text
35: /// <object> SP missing LF
36: /// ```
37: ///
38: /// (git also reports `<object> SP ambiguous LF` for a ref that resolves to
39: /// more than one object; `<commit>:<path>` syntax should never be
40: /// ambiguous, but it's checked for explicitly below rather than silently
41: /// falling through to the blob-header parse.)
42: ///
43: /// This lets every canonical manifest's content at one commit be fetched in
44: /// a single subprocess round trip instead of one `git show` per manifest.
45: ///
46: /// Parsing here is deliberately defensive rather than permissive: this
47: /// feeds [`derive_release_commit_decision`]'s trust-boundary comparison, so
48: /// any framing ambiguity -- an unrecognized header shape, a declared `size`
49: /// that doesn't fit the remaining output, a missing separator byte right
50: /// after the declared content length, a non-`blob` object type, or a
51: /// leftover/truncated tail once every requested path has been accounted
52: /// for -- fails the whole batch closed rather than guessing. Each expected
53: /// response is also matched against its exact requested object string
54: /// (rather than a generic "ends with ` missing`" pattern), so a manifest
55: /// path that happened to contain a space or colon can't be misread as a
56: /// different response shape. Silently misattributing one manifest's
57: /// content to a different path because an undetected desync shifted every
58: /// later offset would be a far worse failure mode than an outright
59: /// rejection.
60: pub(crate) fn batch_blobs<R: CommandRunner + ?Sized>(
61:     runner: &R,
62:     root: &std::path::Path,
63:     objects: &[String],
64: ) -> Result<Vec<BatchBlob>, GraphError> {
65:     if objects.is_empty() {
66:         return Ok(Vec::new());
67:     }
69:     const BATCH_ARGS: [&str; 2] = ["cat-file", "--batch"];
71:     let mut stdin = String::new();
72:     for object in objects {
73:         stdin.push_str(object);
74:         stdin.push('\n');
75:     }
77:     let output = runner.run_with_stdin("git", &BATCH_ARGS, root, stdin.as_bytes())?;
78:     if !output.success() {
79:         return Err(command_non_zero_exit("git", &BATCH_ARGS, &output));
80:     }
82:     let mut rest = output.stdout.as_str();
83:     let mut results = Vec::with_capacity(objects.len());
84:     for object in objects {
85:         let (header, after_header) = rest.split_once('\n').ok_or_else(|| {
86:             command_malformed_output(
87:                 "git",
88:                 &BATCH_ARGS,
89:                 format!("truncated response: missing header line for `{object}`"),
90:             )
91:         })?;
93:         if header == format!("{object} missing") {
94:             results.push(BatchBlob::Missing);
95:             rest = after_header;
96:             continue;
97:         }
98:         if header == format!("{object} ambiguous") {
99:             return Err(command_malformed_output(
100:                 "git",
101:                 &BATCH_ARGS,
102:                 format!("object `{object}` is ambiguous"),
103:             ));
104:         }
106:         let mut fields = header.split(' ');
107:         let sha = fields.next().ok_or_else(|| {
108:             command_malformed_output(
109:                 "git",
110:                 &BATCH_ARGS,
111:                 format!("header for `{object}` is missing its sha field: `{header}`"),
112:             )
113:         })?;
114:         let object_type = fields.next().ok_or_else(|| {
115:             command_malformed_output(
116:                 "git",
117:                 &BATCH_ARGS,
118:                 format!("header for `{object}` is missing its type field: `{header}`"),
119:             )
120:         })?;
121:         let size_field = fields.next().ok_or_else(|| {
122:             command_malformed_output(
123:                 "git",
124:                 &BATCH_ARGS,
125:                 format!("header for `{object}` is missing its size field: `{header}`"),
126:             )
127:         })?;
128:         if fields.next().is_some() {
129:             // A well-formed header has exactly three space-separated
130:             // fields; anything else is not a shape this parser understands.
131:             return Err(command_malformed_output(
132:                 "git",
133:                 &BATCH_ARGS,
134:                 format!("header for `{object}` has more than three fields: `{header}`"),
135:             ));
136:         }
137:         if sha.is_empty() || !sha.chars().all(|c| c.is_ascii_hexdigit()) {
138:             return Err(command_malformed_output(
139:                 "git",
140:                 &BATCH_ARGS,
141:                 format!("header for `{object}` reports a non-hex sha: `{sha}`"),
142:             ));
143:         }
144:         if object_type != "blob" {
145:             // Every path requested here is a canonical manifest file, so a
146:             // resolved object must be a blob; a tree/commit/tag response
147:             // means the path resolved to something else entirely.
148:             return Err(command_malformed_output(
149:                 "git",
150:                 &BATCH_ARGS,
151:                 format!("object `{object}` resolved to a `{object_type}`, not a blob"),
152:             ));
153:         }
154:         let size: usize = size_field.parse().map_err(|parse_error| {
155:             command_malformed_output(
156:                 "git",
157:                 &BATCH_ARGS,
158:                 format!("header for `{object}` has a non-numeric size `{size_field}`: {parse_error}"),
159:             )
160:         })?;
162:         if size > after_header.len() {
163:             return Err(command_malformed_output(
164:                 "git",
165:                 &BATCH_ARGS,
166:                 format!("object `{object}` declares size {size}, exceeding the remaining response"),
167:             ));
168:         }
169:         // `.get(..size)` (byte-indexed) rather than raw slicing: if `size`
170:         // doesn't land on a UTF-8 char boundary this fails closed instead
171:         // of panicking.
172:         let content = after_header.get(..size).ok_or_else(|| {
173:             command_malformed_output(
174:                 "git",
175:                 &BATCH_ARGS,
176:                 format!("object `{object}` declares size {size} that does not land on a UTF-8 boundary"),
177:             )
178:         })?;
179:         let remainder = &after_header[size..];
180:         // The protocol always emits exactly one LF right after the
181:         // content, separate from the content itself. Requiring it here
182:         // catches a desynced `size` (from an earlier, unexpectedly
183:         // reencoded entry) as an explicit error instead of silently
184:         // parsing the wrong bytes as this entry's content.
185:         if remainder.as_bytes().first() != Some(&b'\n') {
186:             return Err(command_malformed_output(
187:                 "git",
188:                 &BATCH_ARGS,
189:                 format!("object `{object}` content is not followed by the expected newline separator"),
190:             ));
191:         }
192:         results.push(BatchBlob::Blob(content.to_string()));
193:         rest = &remainder[1..];
194:     }
196:     if !rest.is_empty() {
197:         // More output than the requested objects account for -- either an
198:         // extra unexpected reply or a framing desync earlier in the
199:         // stream. Either way, fail closed rather than ignore it.
200:         return Err(command_malformed_output(
201:             "git",
202:             &BATCH_ARGS,
203:             "response contained more data than the requested objects account for",
204:         ));
205:     }
207:     Ok(results)
208: }
