25: fn map_reason_to_change_source(
26:     reason: &BumpReason,
27:     id: &callisto_model::PackageId,
28:     to: &callisto_model::Version,
29:     outcome: &crate::cascade::CascadeOutcome,
30:     agg: &crate::aggregate::Aggregation,
31: ) -> Option<ChangeSource> {
32:     match reason {
33:         BumpReason::FixedGroupUnion { group } => Some(ChangeSource::GroupUnion {
34:             group: group.clone(),
35:             kind: GroupKind::Fixed,
36:         }),
37:         BumpReason::LinkedGroupUnion { group } => Some(ChangeSource::GroupUnion {
38:             group: group.clone(),
39:             kind: GroupKind::Linked,
40:         }),
41:         BumpReason::Cascade {
42:             via,
43:             dep_kind,
44:             dependency_to,
45:             ..
46:         } => Some(ChangeSource::DependencyUpdate {
47:             dependency: via.clone(),
48:             dep_kind: *dep_kind,
49:             to: dependency_to.clone(),
50:         }),
51:         BumpReason::PeerEscalation { via, .. } => {
52:             let dep_to = outcome.targets.get(via).cloned().unwrap_or_else(|| to.clone());
53:             Some(ChangeSource::PeerEscalation {
54:                 dependency: via.clone(),
55:                 to: dep_to,
56:             })
57:         }
58:         BumpReason::Inference { commits, .. } => match agg.inference_commits.get(id).and_then(|c| c.first()) {
59:             Some((sha, subject)) => Some(ChangeSource::Commit {
60:                 sha: sha.clone(),
61:                 subject: subject.clone(),
62:             }),
63:             None => Some(ChangeSource::Changeset {
64:                 filename: String::new(),
65:                 summary: format!("Inferred version bump ({commits} commit(s))"),
66:             }),
67:         },
68:         _ => None,
69:     }
70: }
72: pub fn plan_version<R: CommandRunner, D: DependencyResolver, I: SeverityInference>(
73:     ws: &Workspace<'_, R, D>,
74:     inference: &I,
75:     opts: &VersionOptions,
76: ) -> Result<VersionPlan, GraphError> {
77:     let base_versions = ws.base_versions()?;
78:     let tags = ws.tags()?;
80:     let pre_path = ws.root.join(ws.config.pre_json_path());
81:     let pre_text = callisto_model::strict_fs::read_optional(&pre_path).map_err(|e| GraphError::PreJsonRead {
82:         path: pre_path.clone(),
83:         message: e.to_string(),
84:     })?;
85:     let (pre_state, pre_json_original_text) = if let Some(text) = pre_text {
86:         let state = callisto_model::format::parse_pre_json(&text).map_err(GraphError::PreJson)?;
87:         let state = ws.resolve_pre_state_from_json(state, &text)?;
88:         (Some(state), Some(text))
89:     } else {
90:         (None, None)
91:     };
93:     let mut agg = aggregate(
94:         &ws.graph,
95:         &ws.identity,
96:         &ws.config,
97:         ws.git_access(),
98:         tags,
99:         &base_versions,
100:         pre_state.as_ref(),
101:         inference,
102:     )?;
104:     // For PreMode::Exit, inject a synthetic Patch severity for every package
105:     // that is currently at a pre-release version. This triggers bump_target
106:     // (which in Exit mode calls versioning.bump on the pre-release, stripping
107:     // the tag and finalizing to stable) even when no pending changeset files
108:     // exist on disk — they were consumed and deleted during the pre-release phase
109:     // and their stems recorded in pre.json.
110:     if let Some(ref pre) = pre_state
111:         && pre.mode == callisto_model::format::PreMode::Exit
112:     {
113:         for (id, ver) in &base_versions {
114:             if ver.is_prerelease() {
115:                 agg.severities.entry(id.clone()).or_insert(Severity::Patch);
116:                 agg.reasons
117:                     .entry(id.clone())
118:                     .or_insert(BumpReason::PreRelease { tag: pre.tag.clone() });
119:             }
120:         }
121:     }
123:     let input = CascadeInput {
124:         graph: &ws.graph,
125:         groups: &ws.config.groups,
126:         cfg: &ws.config.cascade,
127:         seed: &agg.severities,
128:         reasons: &agg.reasons,
129:         named_by: &agg.named_by,
130:         base: &base_versions,
131:         pre: pre_state.as_ref(),
132:         tags,
133:         identity: &ws.identity,
134:     };
136:     let napi = crate::napi::NapiTargetsIndex::load(&ws.config.groups, &ws.root, &ws.graph)?;
137:     let group_check =
138:         crate::groups::pre_mutation_checks(&ws.graph, &ws.config.groups, &base_versions, tags, &napi, &ws.root)?;
140:     let outcome = run_cascade(input)?;
142:     let mut bumps = Vec::new();
143:     let mut changelog_writes = Vec::new();
145:     // PERF-006: build a map once so each lookup inside the loop is O(1)
146:     // instead of O(N) (the previous packages().find() call).
147:     let pkg_map: HashMap<_, _> = ws.graph.packages().map(|p| (&p.id, p)).collect();
149:     for (id, &sev) in &outcome.severities {
150:         if sev == Severity::None {
151:             continue;
152:         }
153:         let pkg = pkg_map
154:             .get(id)
155:             .copied()
156:             .expect("every bumped package is in the workspace");
157:         let from = base_versions.get(id).cloned().ok_or_else(|| {
158:             GraphError::Manifest(callisto_model::ManifestError::MissingField {
159:                 path: pkg.manifests.first().map(|m| m.path.clone()).unwrap_or_default(),
160:                 field: "version",
161:             })
162:         })?;
163:         let to = outcome.targets.get(id).cloned().ok_or_else(|| {
164:             GraphError::Manifest(callisto_model::ManifestError::MissingField {
165:                 path: pkg.manifests.first().map(|m| m.path.clone()).unwrap_or_default(),
166:                 field: "version",
167:             })
168:         })?;
170:         let mut writes = Vec::new();
171:         for decl in &pkg.manifests {
172:             if decl.role == callisto_model::ManifestRole::Canonical {
173:                 writes.push(VersionWriteTarget::Manifest(decl.path.clone()));
174:             }
175:         }
177:         bumps.push(PlannedBump {
178:             package: id.clone(),
179:             from: from.clone(),
180:             to: to.clone(),
181:             severity: sev,
182:             governed_by: outcome.governed_by.get(id).cloned(),
183:             reason: outcome.reasons.get(id).cloned(),
184:             writes,
185:         });
187:         if let Some(ch_path) = &pkg.changelog {
188:             let mut input = match agg.changelog_inputs.get(id).cloned() {
189:                 Some(mut agg_input) => {
190:                     // Real changeset data: use it, but set the resolved target version.
191:                     agg_input.from = from.clone();
192:                     agg_input.to = Some(to.clone());
193:                     if let Some(reason) = outcome.reasons.get(id)
194:                         && let Some(source) = map_reason_to_change_source(reason, id, &to, &outcome, &agg)
195:                     {
196:                         agg_input.entries.push(ChangelogEntry { severity: sev, source });
197:                     }
198:                     agg_input
199:                 }
200:                 _ => {
201:                     // No changeset drove this bump (cascade, group, inference, pre-release).
202:                     // Synthesize a single entry describing the reason so that render_section()
203:                     // never receives an empty entries list (which returns EmptyInput).
204:                     let source = outcome
205:                         .reasons
206:                         .get(id)
207:                         .and_then(|r| map_reason_to_change_source(r, id, &to, &outcome, &agg))
208:                         .unwrap_or_else(|| ChangeSource::Changeset {
209:                             filename: String::new(),
210:                             summary: format!(
211:                                 "Version bump ({})",
212:                                 match sev {
213:                                     Severity::Major => "major",
214:                                     Severity::Minor => "minor",
215:                                     Severity::Patch => "patch",
216:                                     Severity::None => "none",
217:                                 }
218:                             ),
219:                         });
220:                     ChangelogInput {
221:                         package: id.clone(),
222:                         from: from.clone(),
223:                         to: Some(to.clone()),
224:                         entries: vec![ChangelogEntry { severity: sev, source }],
225:                     }
226:                 }
227:             };
229:             if let Some(group_name) = group_check
230:                 .new_members
231:                 .iter()
232:                 .find(|(_, members)| members.contains(id))
233:                 .map(|(name, _)| name.clone())
234:             {
235:                 input.entries.push(ChangelogEntry {
236:                     severity: sev,
237:                     source: ChangeSource::NewGroupMember { group: group_name },
238:                 });
239:             }
241:             changelog_writes.push(crate::plan::ChangelogWrite {
242:                 changelog_path: ch_path.clone(),
243:                 input,
244:             });
245:         }
246:     }
248:     let is_pre_mode = pre_state
249:         .as_ref()
250:         .map(|s| s.mode == callisto_model::format::PreMode::Pre)
251:         .unwrap_or(false);
252:     // In pre mode a changeset already recorded in pre.json is not pending: a rerun plans nothing for it.
253:     let nothing_pending = if is_pre_mode {
254:         agg.new_pre_changesets.is_empty()
255:     } else {
256:         agg.consumed.is_empty()
257:     };
259:     // Reading the changesets comes first: an entry that names no package leaves its changeset on disk.
260:     let mut diagnostics = agg.diagnostics.clone();
261:     diagnostics.extend(outcome.diagnostics);
262:     diagnostics.extend(group_check.diagnostics);
263:     if nothing_pending && !opts.allow_empty_changesets && !ws.config.validation.allow_empty_changesets {
264:         diagnostics.push(callisto_model::Diagnostic {
265:             code: callisto_model::DiagnosticCode::EmptyChangeset,
266:             severity: callisto_model::DiagnosticSeverity::Warning,
267:             message: "No pending changesets found in workspace".to_string(),
268:             package: None,
269:             path: None,
270:             escalated_by: Some(callisto_model::StrictFlag::Strict),
271:             governed_by: Some(callisto_model::ConfigKey::VALIDATION_ALLOW_EMPTY_CHANGESETS),
272:         });
273:     }
275:     escalate(&mut diagnostics, opts.strict);
277:     let (pre_state_update, delete_pre_json) = if let Some(mut state) = pre_state {
278:         if state.mode == callisto_model::format::PreMode::Exit {
279:             (None, Some(ws.config.pre_json_path()))
280:         } else {
281:             // Records ids aggregate() determined are newly-seen this run; see Aggregation::new_pre_changesets.
282:             for id in &agg.new_pre_changesets {
283:                 if !state.changesets.iter().any(|s| s == id) {
284:                     state.changesets.push(id.clone());
285:                 }
286:             }
287:             (Some(state), None)
288:         }
289:     } else {
290:         (None, None)
291:     };
293:     let targets = bumps.iter().map(|b| (b.package.clone(), b.to.clone())).collect();
294:     let (platform_writes, optional_dep_updates) = platform_version_writes(ws, &targets)?;
296:     Ok(VersionPlan {
297:         bumps,
298:         rewrites: outcome.rewrites.into_values().collect(),
299:         platform_writes,
300:         optional_dep_updates,
301:         changelog_writes,
302:         consumed_changesets: agg.consumed,
303:         pre_state_update,
304:         pre_json_path: ws.config.pre_json_path(),
305:         pre_json_original_text,
306:         delete_pre_json,
307:         pre_cursor_updates: Vec::new(),
308:         observed_versions: base_versions,
309:         diagnostics,
310:     })
311: }
313: /// Refuses when a canonical manifest version differs from `HEAD` while release inputs remain or the change is staged.
314: pub fn check_partial_run<R: CommandRunner, D: DependencyResolver>(ws: &Workspace<'_, R, D>) -> Result<(), GraphError> {
315:     let head = match ws.git_access().head_sha() {
316:         Ok(head) => head,
317:         Err(error) => {
318:             let output = ws
319:                 .runner
320:                 .run("git", &["rev-parse", "--verify", "--quiet", "HEAD"], &ws.root)
321:                 .map_err(GraphError::Command)?;
322:             match output.exit_code {
323:                 Some(1) => return Ok(()),
324:                 Some(0) => return Err(error.into()),
325:                 exit_code => {
326:                     return Err(GraphError::Command(callisto_model::CommandError::Failed {
327:                         program: "git".to_string(),
328:                         exit_code,
329:                         stderr: output.stderr,
330:                     }))
331:                 }
332:             }
333:         }
334:     };
335:     let head = head.as_str();
337:     // A pre-release cycle legitimately reruns `version` uncommitted; the staged-manifest check is scoped past it.
338:     let pre_mode = {
339:         let path = ws.root.join(ws.config.pre_json_path());
340:         let text = callisto_model::strict_fs::read_optional(&path).map_err(|e| GraphError::PreJsonRead {
341:             path: path.clone(),
342:             message: e.to_string(),
343:         })?;
344:         if let Some(text) = text {
345:             let state = callisto_model::format::parse_pre_json(&text).map_err(GraphError::PreJson)?;
346:             Some(state.mode)
347:         } else {
348:             None
349:         }
350:     };
351:     let in_pre_release_cycle = pre_mode == Some(callisto_model::format::PreMode::Pre);
353:     let changed = SourceChanges::since(ws, head)?;
354:     // The paths that can set each manifest's version are found once and used by both passes below.
355:     let mut sources: HashMap<std::path::PathBuf, Vec<String>> = HashMap::new();
356:     let staged_manifests = if in_pre_release_cycle {
357:         BTreeSet::new()
358:     } else {
359:         canonical_manifest_staged_paths(ws, head, &changed, &mut sources)?
360:     };
361:     let pending = !in_pre_release_cycle
362:         && (head_has_pending_changeset(ws, head)?
363:             || working_tree_has_pending_changeset(ws)?
364:             || !staged_manifests.is_empty());
365:     if !pending {
366:         return Ok(());
367:     }
369:     let head_texts = RefCell::new(HashMap::new());
370:     let index_texts = RefCell::new(HashMap::new());
371:     prefetch_head_manifests(ws, head, &head_texts)?;
372:     let mut head_reads = callisto_manifests::WorkspaceReads::default();
373:     let mut index_reads = callisto_manifests::WorkspaceReads::default();
374:     let base_versions = ws.base_versions()?;
375:     for pkg in ws.graph.packages() {
376:         let Some(disk) = base_versions.get(&pkg.id) else {
377:             continue;
378:         };
379:         for decl in pkg.canonical_manifests() {
380:             let path = super::release_decision::normalized_git_path(&decl.path)?;
381:             let Some(head_version) = manifest_version_at(ws, head, &path, &head_texts, &mut head_reads)? else {
382:                 continue;
383:             };
384:             let index_path_changed = version_sources(ws, head, &changed, decl, &mut sources)?
385:                 .iter()
386:                 .any(|source| staged_manifests.contains(source));
387:             let index_version = if index_path_changed {
388:                 manifest_version_in_index(ws, head, &path, &index_texts, &mut index_reads)?
389:             } else {
390:                 None
391:             };
392:             let index_display = match &index_version {
393:                 Some(version) => version.version.render().to_string(),
394:                 None if index_path_changed => "absent".to_string(),
395:                 None => head_version.version.render().to_string(),
396:             };
397:             let index_differs = index_path_changed
398:                 && index_version
399:                     .as_ref()
400:                     .is_none_or(|version| version.version != head_version.version);
401:             let completing_prerelease = pre_mode == Some(callisto_model::format::PreMode::Exit)
402:                 && disk.is_prerelease()
403:                 && (!index_path_changed
404:                     || index_version
405:                         .as_ref()
406:                         .is_some_and(|version| version.version.is_prerelease()));
407:             if completing_prerelease {
408:                 continue;
409:             }
410:             if *disk != head_version.version || index_differs {
411:                 return Err(GraphError::PartialVersionRun {
412:                     path: head_version.authority,
413:                     disk: disk.clone(),
414:                     index: index_display,
415:                     head: head_version.version,
416:                 });
417:             }
418:         }
419:     }
421:     Ok(())
422: }
