452: /// True when an untracked or tracked changeset remains in the configured directory on disk.
453: fn working_tree_has_pending_changeset<R: CommandRunner, D: DependencyResolver>(
454:     ws: &Workspace<'_, R, D>,
455: ) -> Result<bool, GraphError> {
456:     let dir = ws.root.join(&ws.config.changesets_dir);
457:     let files = crate::aggregate::list_changeset_files(&dir).map_err(|error| GraphError::ApplyIo {
458:         path: ws.config.changesets_dir.clone(),
459:         message: error.to_string(),
460:     })?;
461:     Ok(!files.is_empty())
462: }
464: /// True when a canonical manifest differs between index and HEAD: `git add`ed by a prior `apply` but never committed.
465: fn canonical_manifest_staged_paths<R: CommandRunner, D: DependencyResolver>(
466:     ws: &Workspace<'_, R, D>,
467:     head: &str,
468:     changed: &SourceChanges,
469:     sources: &mut HashMap<std::path::PathBuf, Vec<String>>,
470: ) -> Result<BTreeSet<String>, GraphError> {
471:     let mut paths = BTreeSet::new();
472:     for decl in ws.graph.packages().flat_map(|pkg| pkg.canonical_manifests()) {
473:         paths.extend(version_sources(ws, head, changed, decl, sources)?);
474:     }
475:     // The index-versus-HEAD diff `SourceChanges` already read answers this for every path at once.
476:     Ok(paths.into_iter().filter(|path| changed.staged.contains(path)).collect())
477: }
479: /// Whether `<rev>:<path>` names an object; `--quiet` keeps a missing path from printing to stderr.
480: fn head_object_exists<R: CommandRunner, D: DependencyResolver>(
481:     ws: &Workspace<'_, R, D>,
482:     spec: &str,
483: ) -> Result<bool, GraphError> {
484:     let output = ws
485:         .runner
486:         .run("git", &["rev-parse", "--verify", "--quiet", spec], &ws.root)
487:         .map_err(GraphError::Command)?;
488:     match output.exit_code {
489:         Some(0) => Ok(true),
490:         Some(1) => Ok(false),
491:         exit_code => Err(GraphError::Command(callisto_model::CommandError::Failed {
492:             program: "git".to_string(),
493:             exit_code,
494:             stderr: output.stderr,
495:         })),
496:     }
497: }
499: /// True when `HEAD`'s tree still has an unconsumed changeset file, read from the commit, not the working tree.
500: fn head_has_pending_changeset<R: CommandRunner, D: DependencyResolver>(
501:     ws: &Workspace<'_, R, D>,
502:     head: &str,
503: ) -> Result<bool, GraphError> {
504:     let dir = super::release_decision::normalized_git_path(&ws.config.changesets_dir)?;
505:     let spec = format!("{head}:{dir}");
506:     if !head_object_exists(ws, &spec)? {
507:         // The changesets directory didn't exist at HEAD (e.g. the first `version` run); nothing left pending.
