572: /// The paths that differ from `HEAD` in the working tree or the index, and those that differ in the index alone.
573: struct SourceChanges {
574:     changed: BTreeSet<String>,
575:     staged: BTreeSet<String>,
576: }
578: impl SourceChanges {
579:     fn since<R: CommandRunner, D: DependencyResolver>(
580:         ws: &Workspace<'_, R, D>,
581:         head: &str,
582:     ) -> Result<Self, GraphError> {
583:         let mut changed = BTreeSet::new();
584:         let mut staged = BTreeSet::new();
585:         let working_tree = vec!["diff", "--name-only", "-z", head];
586:         let index = vec!["diff", "--cached", "--name-only", "-z", head];
587:         for (args, is_index) in [(working_tree, false), (index, true)] {
588:             let output = ws.runner.run("git", &args, &ws.root).map_err(GraphError::Command)?;
589:             if !output.success() {
590:                 return Err(GraphError::Command(callisto_model::CommandError::Failed {
591:                     program: "git".to_string(),
592:                     exit_code: output.exit_code,
593:                     stderr: output.stderr,
594:                 }));
595:             }
596:             let paths = output
597:                 .stdout
598:                 .split('\0')
599:                 .filter(|path| !path.is_empty())
600:                 .map(str::to_owned);
601:             if is_index {
602:                 let paths: Vec<String> = paths.collect();
603:                 staged.extend(paths.iter().cloned());
604:                 changed.extend(paths);
605:             } else {
606:                 changed.extend(paths);
607:             }
608:         }
609:         Ok(SourceChanges { changed, staged })
610:     }
611: }
613: /// [`version_source_paths`], remembered per manifest.
614: fn version_sources<R: CommandRunner, D: DependencyResolver>(
615:     ws: &Workspace<'_, R, D>,
616:     head: &str,
617:     changed: &SourceChanges,
618:     decl: &callisto_model::ManifestDecl,
619:     memo: &mut HashMap<std::path::PathBuf, Vec<String>>,
620: ) -> Result<Vec<String>, GraphError> {
621:     if let Some(known) = memo.get(&decl.path) {
622:         return Ok(known.clone());
623:     }
624:     let sources = version_source_paths(ws, head, changed, decl)?;
625:     memo.insert(decl.path.clone(), sources.clone());
626:     Ok(sources)
627: }
629: /// Every path whose staged change could alter the effective version of `decl`: its own manifest and, for Cargo, each
630: /// manifest that could be the workspace root it inherits from. That includes the workspace the package names in the
631: /// working tree, and, when its own manifest has changed since `HEAD`, the one it named at `HEAD` and in the index.
632: fn version_source_paths<R: CommandRunner, D: DependencyResolver>(
633:     ws: &Workspace<'_, R, D>,
634:     head: &str,
635:     changed: &SourceChanges,
636:     decl: &callisto_model::ManifestDecl,
637: ) -> Result<Vec<String>, GraphError> {
638:     let own = super::release_decision::normalized_git_path(&decl.path)?;
639:     let mut sources = vec![own.clone()];
640:     if decl.ecosystem() == callisto_model::Ecosystem::Cargo {
641:         for candidate in callisto_manifests::workspace_manifest_candidates(&ws.root, &decl.path)? {
642:             sources.push(super::release_decision::normalized_git_path(&candidate)?);
643:         }
644:         if changed.changed.contains(&own) {
645:             for text in [manifest_blob_at(ws, head, &own)?, manifest_blob_in_index(ws, &own)?]
646:                 .into_iter()
647:                 .flatten()
648:             {
649:                 if let Some(named) = callisto_manifests::named_workspace_manifest(&decl.path, &text)? {
650:                     sources.push(super::release_decision::normalized_git_path(&named)?);
651:                 }
652:             }
653:         }
654:     }
655:     Ok(sources)
656: }
658: /// Manifest text by normalized path, fetched at most once per path.
659: type ManifestTexts = RefCell<HashMap<String, Option<String>>>;
661: fn cached_text(
662:     texts: &ManifestTexts,
663:     path: &std::path::Path,
664:     fetch: impl FnOnce(&str) -> Result<Option<String>, GraphError>,
665: ) -> Result<Option<String>, GraphError> {
666:     let key = super::release_decision::normalized_git_path(path)?;
667:     if let Some(text) = texts.borrow().get(&key) {
668:         return Ok(text.clone());
669:     }
670:     let text = fetch(&key)?;
671:     texts.borrow_mut().insert(key, text.clone());
672:     Ok(text)
673: }
675: fn manifest_version_at<R: CommandRunner, D: DependencyResolver>(
676:     ws: &Workspace<'_, R, D>,
677:     head: &str,
678:     path: &str,
679:     texts: &ManifestTexts,
680:     reads: &mut callisto_manifests::WorkspaceReads,
681: ) -> Result<Option<callisto_manifests::EffectiveManifestVersion>, GraphError> {
682:     let path = std::path::Path::new(path);
683:     let Ok(format) = callisto_model::ManifestFormat::from_path(path) else {
684:         return Ok(None);
685:     };
686:     let at_head = |other: &std::path::Path| cached_text(texts, other, |key| manifest_blob_at(ws, head, key));
687:     let Some(source) = at_head(path)? else {
688:         return Ok(None);
689:     };
690:     callisto_manifests::read_effective_version(format, &source, path, reads, at_head)
691: }
693: /// The version `path` has in the index; manifests it inherits from that the index lacks are read from `head`.
694: fn manifest_version_in_index<R: CommandRunner, D: DependencyResolver>(
695:     ws: &Workspace<'_, R, D>,
696:     head: &str,
697:     path: &str,
698:     texts: &ManifestTexts,
699:     reads: &mut callisto_manifests::WorkspaceReads,
700: ) -> Result<Option<callisto_manifests::EffectiveManifestVersion>, GraphError> {
701:     let manifest_path = std::path::Path::new(path);
702:     let Ok(format) = callisto_model::ManifestFormat::from_path(manifest_path) else {
703:         return Ok(None);
704:     };
705:     let Some(source) = manifest_blob_in_index(ws, path)? else {
706:         return Ok(None);
707:     };
708:     let in_index_or_head = |other: &std::path::Path| {
709:         cached_text(texts, other, |key| match manifest_blob_in_index(ws, key)? {
710:             Some(text) => Ok(Some(text)),
711:             None => manifest_blob_at(ws, head, key),
712:         })
713:     };
714:     callisto_manifests::read_effective_version(format, &source, manifest_path, reads, in_index_or_head)
715: }
717: /// Platform manifest version writes and owner `optionalDependencies` pin updates
718: /// for every owner with a target version in `targets`. Sources: each owner's
719: /// attached platform manifests, plus `[[fixed-group]]`
720: /// platform members.
721: pub(crate) fn platform_version_writes<R: CommandRunner, D: DependencyResolver>(
722:     ws: &Workspace<'_, R, D>,
723:     targets: &std::collections::BTreeMap<callisto_model::PackageId, callisto_model::Version>,
724: ) -> Result<(Vec<PlatformWrite>, Vec<crate::plan::OptionalDepUpdate>), GraphError> {
725:     let open_ctx = OpenContext::for_workspace_root(&ws.root)?;
726:     let pkg_map: HashMap<_, _> = ws.graph.packages().map(|p| (&p.id, p)).collect();
728:     let mut members: Vec<(&callisto_model::PackageId, &std::path::Path, &str)> = Vec::new();
729:     for pkg in ws.graph.packages() {
730:         members.extend(
731:             ws.identity
732:                 .attached_platforms(pkg)
733:                 .map(|(name, path)| (&pkg.id, path, name)),
734:         );
735:     }
736:     for group in ws.config.groups.fixed.values() {
737:         for member in group.members(GroupMemberKind::PlatformManifest) {
738:             if let GroupMember::PlatformManifest { owner, path, name, .. } = member {
739:                 members.push((owner, path, name));
740:             }
741:         }
742:     }
744:     let mut seen = HashSet::new();
745:     let mut platform_writes = Vec::new();
746:     let mut optional_dep_map: std::collections::BTreeMap<std::path::PathBuf, Vec<(String, callisto_model::Version)>> =
747:         std::collections::BTreeMap::new();
748:     for (owner, path, name) in members {
749:         let Some(to) = targets.get(owner) else {
750:             continue;
751:         };
752:         if !seen.insert(path) {
753:             continue;
754:         }
755:         let fmt = callisto_model::ManifestFormat::from_path(path)?;
756:         let decl = callisto_model::ManifestDecl::new(path, ManifestRole::Canonical, fmt)?;
757:         let handle = open(&decl, &open_ctx)?;
758:         let current = handle.current_version()?;
759:         platform_writes.push(PlatformWrite {
760:             manifest: path.to_path_buf(),
761:             version: to.clone(),
762:             from: current,
763:         });
765:         // A dual-manifest owner declares its platforms in package.json, not Cargo.toml.
766:         for owner_decl in pkg_map.get(owner).into_iter().flat_map(|p| p.canonical_manifests()) {
767:             let owner_fmt = callisto_model::ManifestFormat::from_path(&owner_decl.path)?;
768:             let owner_manifest_decl =
769:                 callisto_model::ManifestDecl::new(owner_decl.path.clone(), ManifestRole::Canonical, owner_fmt)?;
770:             // Cached: owner manifest is shared across every platform target under it.
771:             let owner_handle = crate::manifest_cache::open_cached(&ws.manifest_cache, &owner_manifest_decl, &open_ctx)?;
772:             if owner_handle
773:                 .iter_dependencies()
774:                 .any(|dep| dep.kind == callisto_model::DepKind::Optional && dep.name == name)
775:             {
776:                 optional_dep_map
777:                     .entry(owner_decl.path.clone())
778:                     .or_default()
779:                     .push((name.to_string(), to.clone()));
780:                 break;
781:             }
782:         }
783:     }
784:     let optional_dep_updates = optional_dep_map
785:         .into_iter()
786:         .map(|(manifest, updates)| crate::plan::OptionalDepUpdate { manifest, updates })
787:         .collect();
788:     Ok((platform_writes, optional_dep_updates))
789: }

