715: }
717: /// Platform manifest version writes and owner `optionalDependencies` pin updates
718: /// for every owner with a target version in `targets`. Sources: each owner's
719: /// attached platform manifests, plus `[[fixed-group]]`
720: /// platform members.
721: pub(crate) fn platform_version_writes<R: CommandRunner, D: DependencyResolver>(
722:     ws: &Workspace<'_, R, D>,
723:     targets: &std::collections::BTreeMap<callisto_model::PackageId, callisto_model::Version>,
724: ) -> Result<(Vec<PlatformWrite>, Vec<crate::plan::OptionalDepUpdate>), GraphError> {
725:     let open_ctx = OpenContext::for_workspace_root(&ws.root)?;
726:     let pkg_map: HashMap<_, _> = ws.graph.packages().map(|p| (&p.id, p)).collect();
728:     let mut members: Vec<(&callisto_model::PackageId, &std::path::Path, &str)> = Vec::new();
729:     for pkg in ws.graph.packages() {
730:         members.extend(
731:             ws.identity
732:                 .attached_platforms(pkg)
733:                 .map(|(name, path)| (&pkg.id, path, name)),
734:         );
735:     }
736:     for group in ws.config.groups.fixed.values() {
737:         for member in group.members(GroupMemberKind::PlatformManifest) {
738:             if let GroupMember::PlatformManifest { owner, path, name, .. } = member {
739:                 members.push((owner, path, name));
740:             }
741:         }
742:     }
744:     let mut seen = HashSet::new();
745:     let mut platform_writes = Vec::new();
746:     let mut optional_dep_map: std::collections::BTreeMap<std::path::PathBuf, Vec<(String, callisto_model::Version)>> =
747:         std::collections::BTreeMap::new();
748:     for (owner, path, name) in members {
749:         let Some(to) = targets.get(owner) else {
750:             continue;
751:         };
752:         if !seen.insert(path) {
753:             continue;
754:         }
755:         let fmt = callisto_model::ManifestFormat::from_path(path)?;
756:         let decl = callisto_model::ManifestDecl::new(path, ManifestRole::Canonical, fmt)?;
757:         let handle = open(&decl, &open_ctx)?;
758:         let current = handle.current_version()?;
759:         platform_writes.push(PlatformWrite {
760:             manifest: path.to_path_buf(),
761:             version: to.clone(),
762:             from: current,
763:         });
765:         // A dual-manifest owner declares its platforms in package.json, not Cargo.toml.
766:         for owner_decl in pkg_map.get(owner).into_iter().flat_map(|p| p.canonical_manifests()) {
767:             let owner_fmt = callisto_model::ManifestFormat::from_path(&owner_decl.path)?;
768:             let owner_manifest_decl =
769:                 callisto_model::ManifestDecl::new(owner_decl.path.clone(), ManifestRole::Canonical, owner_fmt)?;
770:             // Cached: owner manifest is shared across every platform target under it.
771:             let owner_handle = crate::manifest_cache::open_cached(&ws.manifest_cache, &owner_manifest_decl, &open_ctx)?;
772:             if owner_handle
773:                 .iter_dependencies()
774:                 .any(|dep| dep.kind == callisto_model::DepKind::Optional && dep.name == name)
775:             {
776:                 optional_dep_map
777:                     .entry(owner_decl.path.clone())
778:                     .or_default()
779:                     .push((name.to_string(), to.clone()));
780:                 break;
781:             }
782:         }
783:     }
784:     let optional_dep_updates = optional_dep_map
785:         .into_iter()
786:         .map(|(manifest, updates)| crate::plan::OptionalDepUpdate { manifest, updates })
787:         .collect();
788:     Ok((platform_writes, optional_dep_updates))
789: }

