1: //! `callisto init`: first-run fact detection, config rendering, preview, and scaffolding.
3: use std::collections::{BTreeMap, BTreeSet};
4: use std::path::{Path, PathBuf};
6: use callisto_model::{
7:     ApplyPermit, CommandRunner, Diagnostic, DiagnosticCode, DiagnosticSeverity, Ecosystem, GitHubRepository,
8:     InitReport, PublishTarget, TagName, TagTemplate, Version, SCHEMA_VERSION,
9: };
11: use crate::commands::release::{
12:     canonical_root, is_platform_package, optional_git_remote, plan_workspace_release, programs, timeouts,
13:     LocalReleasePlan, LocalReleaseSource,
14: };
15: use crate::config::raw::RawConfig;
16: use crate::error::{ConfigError, GraphError};
17: use crate::{DependencyResolver, ProjectLocator, ResolvedConfig, Workspace};
19: /// Content of the scaffolded `.changeset/README.md`.
20: pub const CHANGESET_README: &str = "# Changesets
22: This directory contains markdown changeset files generated by Callisto CLI (`callisto add`).
23: Each changeset describes a package version bump and associated release summary.
24: ";
26: const CONFIG_HEADER: &str = "# callisto configuration\n";
27: const DEFAULT_TAG_CONVENTION: &str = "{name}@{version}";
28: const SHARED_TAG_CONVENTION: &str = "v{version}";
29: const TAG_CONVENTIONS: [&str; 4] = [
30:     DEFAULT_TAG_CONVENTION,
31:     "{name}-v{version}",
32:     "{name}-{version}",
33:     SHARED_TAG_CONVENTION,
34: ];
36: /// How packages version relative to each other.
37: #[derive(Clone, Copy, Debug, PartialEq, Eq)]
38: pub enum Versioning {
39:     /// Every package shares one version (`[[fixed-group]] name = "all"`).
40:     Fixed,
41:     Independent,
42: }
44: /// One discovered workspace package.
45: #[derive(Clone, Debug, PartialEq, Eq)]
46: pub struct InitPackage {
47:     /// Ecosystem-qualified id, e.g. `cargo/app`.
48:     pub id: String,
49:     pub version: Version,
50:     /// Executables the package builds; empty for a library.
51:     pub bin_names: Vec<String>,
52:     /// Executables provided by Cargo and eligible for Cargo artifact builds.
53:     pub cargo_bin_names: Vec<String>,
54:     /// Ecosystems that provide executables but do not yet have an artifact builder.
55:     pub unsupported_bin_ecosystems: Vec<String>,
56:     /// Latest release tag under the package's detected convention.
57:     pub last_tag: Option<TagName>,
58:     /// Detected `publish-to` targets (`none` omitted).
59:     pub publish_to: Vec<String>,
60:     /// A napi/maturin platform package: never grouped or shipped.
61:     pub platform: bool,
62: }
64: impl InitPackage {
65:     pub fn is_binary(&self) -> bool {
66:         !self.platform && !self.bin_names.is_empty()
67:     }
69:     fn supports_artifact_builder(&self) -> bool {
70:         self.id.starts_with("cargo/") && !self.cargo_bin_names.is_empty()
71:     }
73:     fn name(&self) -> &str {
74:         self.id.split_once('/').map_or(self.id.as_str(), |(_, name)| name)
75:     }
76: }
78: /// Everything `init` detects before asking a question.
79: #[derive(Clone, Debug)]
80: pub struct InitFacts {
81:     pub root: PathBuf,
82:     pub ecosystems: BTreeSet<Ecosystem>,
83:     pub packages: Vec<InitPackage>,
84:     /// Canonical `origin` push URL, or `None` when no `origin` remote is configured.
85:     pub origin: Option<String>,
86:     /// `origin` as a GitHub `owner/repo`, when it is one.
87:     pub origin_repository: Option<GitHubRepository>,
88:     /// Non-default tag templates to write, keyed by qualified package id.
89:     pub tag_templates: BTreeMap<String, String>,
90:     /// `false` in a repository with no commit yet, where no release can be planned.
91:     pub has_commit: bool,
92:     /// A package ships napi/maturin platform builds -- either its own canonical
93:     /// manifest is platform-tagged, or a platform package is attached to it from
94:     /// a sibling directory (`IdentityIndex::platforms_of`, e.g. napi's per-arch
95:     /// packages). Mirrors `commands::release::local::ci_release_route`'s own
96:     /// platform-package check.
97:     pub has_platform_packages: bool,
98:     /// Some package declares `napi.targets` (`callisto matrix`'s napi entries).
99:     pub has_napi_targets: bool,
100:     /// Some package declares `[tool.maturin].targets`.
101:     pub has_maturin_targets: bool,
102: }
104: impl InitFacts {
105:     pub fn binary_packages(&self) -> impl Iterator<Item = &InitPackage> {
106:         self.packages
107:             .iter()
108:             .filter(|package| package.is_binary() && package.supports_artifact_builder())
109:     }
111:     pub fn unsupported_artifact_packages(&self) -> impl Iterator<Item = &InitPackage> {
112:         self.packages
113:             .iter()
114:             .filter(|package| !package.supports_artifact_builder() && !package.unsupported_bin_ecosystems.is_empty())
115:     }
117:     /// Resolves `name` (qualified or bare) to a binary-producing package.
118:     pub fn product_package(&self, name: &str) -> Result<&InitPackage, GraphError> {
119:         let invalid = |reason| GraphError::InitInvalidProductPackage {
120:             package: name.to_owned(),
121:             reason,
122:             candidates: self.binary_packages().map(|package| package.id.clone()).collect(),
123:         };
124:         let found: Vec<&InitPackage> = match self.packages.iter().find(|package| package.id == name) {
125:             Some(package) => vec![package],
126:             None => self.packages.iter().filter(|package| package.name() == name).collect(),
127:         };
128:         match found.as_slice() {
129:             [package] if package.is_binary() && package.supports_artifact_builder() => Ok(package),
130:             [package] if package.is_binary() => Err(GraphError::InitUnsupportedArtifactBuilder {
131:                 package: package.id.clone(),
132:                 ecosystem: package.unsupported_bin_ecosystems.first().cloned().unwrap_or_else(|| {
133:                     package
134:                         .id
135:                         .split_once('/')
136:                         .map_or("unknown", |(ecosystem, _)| ecosystem)
137:                         .to_owned()
138:                 }),
139:             }),
140:             [_] => Err(invalid("it does not produce a binary artifact")),
141:             _ => Err(invalid("it is not a workspace package")),
142:         }
143:     }
144: }
146: /// Opt-in to shipping binaries as GitHub release assets.
147: #[derive(Clone, Debug, PartialEq, Eq)]
148: pub struct BinaryRelease {
149:     /// Qualified id of the product package.
150:     pub product: String,
151:     pub forge_repository: GitHubRepository,
152:     pub targets: Vec<String>,
153: }
155: /// The operator's intent; everything else is detected.
156: #[derive(Clone, Debug, PartialEq, Eq)]
157: pub struct InitAnswers {
158:     pub versioning: Versioning,
159:     pub binaries: Option<BinaryRelease>,
160: }
162: fn io_err(path: &Path) -> impl Fn(std::io::Error) -> GraphError + '_ {
163:     move |error| GraphError::InitIo {
164:         path: path.to_path_buf(),
165:         message: error.to_string(),
166:     }
167: }
169: fn ensure_uninitialized(root: &Path) -> Result<(), GraphError> {
170:     let path = root.join("callisto.toml");
171:     if callisto_model::strict_fs::exists(&path).map_err(io_err(&path))? {
172:         return Err(GraphError::InitAlreadyInitialized { path });
173:     }
174:     Ok(())
175: }
177: fn qualified_id(package: &callisto_model::Package) -> String {
178:     match package.canonical_manifests().next() {
179:         Some(manifest) => format!("{}/{}", manifest.ecosystem().prefix(), package.id.name()),
180:         None => package.id.display_name(),
181:     }
182: }
184: /// Detects the workspace facts `init` reports and builds on.
185: ///
186: /// # Errors
187: ///
188: /// An existing `callisto.toml`, no Git repository, no usable `origin`, or an
189: /// ambiguous tag convention.
190: pub fn detect<L: ProjectLocator, R: CommandRunner>(
191:     root: &Path,
192:     locator: &L,
193:     runner: &R,
194: ) -> Result<InitFacts, GraphError> {
195:     let root = canonical_root(root)?;
196:     ensure_uninitialized(&root)?;
197:     let git_dir = runner.run_with_timeout(programs::GIT, &["rev-parse", "--git-dir"], &root, timeouts::LOCAL_GIT)?;
198:     if git_dir.exit_code != Some(0) {
199:         return Err(GraphError::InitNotGitRepository { root });
200:     }
201:     let origin = optional_git_remote(&root, runner)?;
202:     let head = runner.run_with_timeout(
203:         programs::GIT,
204:         &["rev-parse", "--verify", "--quiet", "HEAD"],
205:         &root,
206:         timeouts::LOCAL_GIT,
207:     )?;
209:     let discovered = Workspace::load(root.clone(), locator, runner)?;
210:     let tag_templates = detect_tag_templates(&discovered)?;
211:     let templates_only = InitFacts {
212:         root: root.clone(),
213:         ecosystems: BTreeSet::new(),
214:         packages: Vec::new(),
215:         origin: origin.as_ref().map(|remote| remote.endpoint.clone()),
216:         origin_repository: origin.as_ref().and_then(|remote| remote.github_repository.clone()),
217:         tag_templates,
218:         has_commit: head.exit_code == Some(0),
219:         has_platform_packages: false,
220:         has_napi_targets: false,
221:         has_maturin_targets: false,
222:     };
223:     let config = resolve_config_text(
224:         &root,
225:         &render_config(
226:             &templates_only,
227:             &InitAnswers {
228:                 versioning: Versioning::Independent,
229:                 binaries: None,
230:             },
231:         ),
232:     )?;
233:     let workspace = Workspace::load_with_config(root.clone(), config, locator, runner)?;
234:     let tags = workspace.tags()?;
235:     let versions = workspace.base_versions()?;
236:     let ctx = callisto_manifests::OpenContext::for_workspace_root(&workspace.root)?;
238:     let mut packages = Vec::new();
239:     for package in workspace.graph.packages() {
240:         let mut bin_names = Vec::new();
241:         let mut cargo_bin_names = Vec::new();
242:         let mut unsupported_bin_ecosystems = BTreeSet::new();
243:         for decl in package.canonical_manifests() {
244:             let manifest = crate::manifest_cache::open_cached(&workspace.manifest_cache, decl, &ctx)?;
245:             let names = manifest.bin_names()?;
246:             if manifest.ecosystem() == Ecosystem::Cargo {
247:                 cargo_bin_names.extend(names.iter().cloned());
248:             } else if !names.is_empty() {
249:                 unsupported_bin_ecosystems.insert(manifest.ecosystem().prefix().to_owned());
250:             }
251:             bin_names.extend(names);
252:         }
253:         packages.push(InitPackage {
254:             id: qualified_id(package),
255:             version: versions[&package.id].clone(),
256:             bin_names,
257:             cargo_bin_names,
258:             unsupported_bin_ecosystems: unsupported_bin_ecosystems.into_iter().collect(),
259:             last_tag: tags.last_tag(&package.id).map(|tag| tag.name.clone()),
260:             publish_to: package
261:                 .publish_to
262:                 .iter()
263:                 .map(|target| target.config_str().to_owned())
264:                 .filter(|target| target != PublishTarget::None.config_str())
265:                 .collect(),
266:             platform: is_platform_package(package),
267:         });
268:     }
269:     packages.sort_by(|a, b| a.id.cmp(&b.id));
270:     let ecosystems = workspace
271:         .graph
272:         .packages()
273:         .flat_map(|package| package.canonical_manifests())
274:         .map(|manifest| manifest.ecosystem())
275:         .collect();
276:     // Counts attached platform packages too: they never get their own `packages` entry,
277:     // so scanning canonical manifests alone finds only co-located ones.
278:     let has_platform_packages = workspace
279:         .graph
280:         .packages()
281:         .any(|package| is_platform_package(package) || workspace.identity.platforms_of(&package.id).next().is_some());
283:     let matrix = crate::commands::matrix::matrix(&workspace, &crate::commands::matrix::MatrixOptions::default())?;
284:     let has_kind = |kind| matrix.platform_targets.values().any(|group| group.kind == kind);
286:     Ok(InitFacts {
287:         ecosystems,
288:         packages,
289:         has_platform_packages,
290:         has_napi_targets: has_kind(callisto_model::PlatformTargetKind::Napi),
291:         has_maturin_targets: has_kind(callisto_model::PlatformTargetKind::Maturin),
292:         ..templates_only
293:     })
294: }
296: /// One tag convention a package's existing tags follow.
297: struct TagMatch {
298:     convention: &'static str,
299:     template: String,
300:     tags: Vec<String>,
301: }
303: /// Matches each package's tags against the candidate conventions; returns the non-default ones to write.
304: fn detect_tag_templates<R: CommandRunner, D: DependencyResolver>(
305:     workspace: &Workspace<'_, R, D>,
306: ) -> Result<BTreeMap<String, String>, GraphError> {
307:     let all_tags = crate::tags::fetch_all_tags(workspace.git_access())?;
308:     let mut matches: BTreeMap<String, Vec<TagMatch>> = BTreeMap::new();
309:     for package in workspace
310:         .graph
311:         .packages()
312:         .filter(|package| !is_platform_package(package))
313:     {
314:         let grammar = package.version_grammar()?;
315:         for convention in TAG_CONVENTIONS {
316:             let rendered = if convention == DEFAULT_TAG_CONVENTION {
317:                 TagTemplate::default_for(&package.id).as_str()
318:             } else {
319:                 convention.replace("{name}", package.id.name())
320:             };
321:             let Ok(template) = TagTemplate::parse(&rendered) else {
322:                 continue;
323:             };
324:             // A leading digit keeps `{name}-{version}` from claiming `{name}-v1.0.0` under PEP 440.
325:             let tags: Vec<String> = all_tags
326:                 .iter()
327:                 .filter(|tag| {
328:                     template.extract_version_str(tag).is_some_and(|version| {
329:                         version.starts_with(|c: char| c.is_ascii_digit()) && Version::parse(version, grammar).is_ok()
330:                     })
331:                 })
332:                 .cloned()
333:                 .collect();
334:             if !tags.is_empty() {
335:                 matches.entry(qualified_id(package)).or_default().push(TagMatch {
336:                     convention,
337:                     template: rendered,
338:                     tags,
339:                 });
340:             }
341:         }
342:     }
344:     let shared: Vec<String> = matches
345:         .iter()
346:         .filter(|(_, found)| found.iter().any(|found| found.convention == SHARED_TAG_CONVENTION))
347:         .map(|(package, _)| package.clone())
348:         .collect();
349:     if shared.len() > 1 {
350:         return Err(GraphError::InitSharedVersionTag { packages: shared });
351:     }
353:     let mut templates = BTreeMap::new();
354:     for (package, found) in matches {
355:         match found.as_slice() {
356:             [only] => {
357:                 if only.convention != DEFAULT_TAG_CONVENTION {
358:                     templates.insert(package, only.template.clone());
359:                 }

