155: /// The operator's intent; everything else is detected.
156: #[derive(Clone, Debug, PartialEq, Eq)]
157: pub struct InitAnswers {
158:     pub versioning: Versioning,
159:     pub binaries: Option<BinaryRelease>,
160: }
162: fn io_err(path: &Path) -> impl Fn(std::io::Error) -> GraphError + '_ {
163:     move |error| GraphError::InitIo {
164:         path: path.to_path_buf(),
165:         message: error.to_string(),
166:     }
167: }
169: fn ensure_uninitialized(root: &Path) -> Result<(), GraphError> {
170:     let path = root.join("callisto.toml");
171:     if callisto_model::strict_fs::exists(&path).map_err(io_err(&path))? {
172:         return Err(GraphError::InitAlreadyInitialized { path });
173:     }
174:     Ok(())
175: }
177: fn qualified_id(package: &callisto_model::Package) -> String {
178:     match package.canonical_manifests().next() {
179:         Some(manifest) => format!("{}/{}", manifest.ecosystem().prefix(), package.id.name()),
180:         None => package.id.display_name(),
181:     }
182: }
184: /// Detects the workspace facts `init` reports and builds on.
185: ///
186: /// # Errors
187: ///
188: /// An existing `callisto.toml`, no Git repository, no usable `origin`, or an
189: /// ambiguous tag convention.
190: pub fn detect<L: ProjectLocator, R: CommandRunner>(
191:     root: &Path,
192:     locator: &L,
193:     runner: &R,
194: ) -> Result<InitFacts, GraphError> {
195:     let root = canonical_root(root)?;
196:     ensure_uninitialized(&root)?;
197:     let git_dir = runner.run_with_timeout(programs::GIT, &["rev-parse", "--git-dir"], &root, timeouts::LOCAL_GIT)?;
198:     if git_dir.exit_code != Some(0) {
199:         return Err(GraphError::InitNotGitRepository { root });
200:     }
201:     let origin = optional_git_remote(&root, runner)?;
202:     let head = runner.run_with_timeout(
203:         programs::GIT,
204:         &["rev-parse", "--verify", "--quiet", "HEAD"],
205:         &root,
206:         timeouts::LOCAL_GIT,
207:     )?;
209:     let discovered = Workspace::load(root.clone(), locator, runner)?;
210:     let tag_templates = detect_tag_templates(&discovered)?;
211:     let templates_only = InitFacts {
212:         root: root.clone(),
213:         ecosystems: BTreeSet::new(),
214:         packages: Vec::new(),
215:         origin: origin.as_ref().map(|remote| remote.endpoint.clone()),
216:         origin_repository: origin.as_ref().and_then(|remote| remote.github_repository.clone()),
217:         tag_templates,
218:         has_commit: head.exit_code == Some(0),
219:         has_platform_packages: false,
220:         has_napi_targets: false,
221:         has_maturin_targets: false,
222:     };
223:     let config = resolve_config_text(
224:         &root,
225:         &render_config(
226:             &templates_only,
227:             &InitAnswers {
228:                 versioning: Versioning::Independent,
229:                 binaries: None,
230:             },
231:         ),
232:     )?;
233:     let workspace = Workspace::load_with_config(root.clone(), config, locator, runner)?;
234:     let tags = workspace.tags()?;
235:     let versions = workspace.base_versions()?;
236:     let ctx = callisto_manifests::OpenContext::for_workspace_root(&workspace.root)?;
238:     let mut packages = Vec::new();
239:     for package in workspace.graph.packages() {
240:         let mut bin_names = Vec::new();
241:         let mut cargo_bin_names = Vec::new();
242:         let mut unsupported_bin_ecosystems = BTreeSet::new();
243:         for decl in package.canonical_manifests() {
244:             let manifest = crate::manifest_cache::open_cached(&workspace.manifest_cache, decl, &ctx)?;
245:             let names = manifest.bin_names()?;
246:             if manifest.ecosystem() == Ecosystem::Cargo {
247:                 cargo_bin_names.extend(names.iter().cloned());
248:             } else if !names.is_empty() {
249:                 unsupported_bin_ecosystems.insert(manifest.ecosystem().prefix().to_owned());
250:             }
251:             bin_names.extend(names);
252:         }
253:         packages.push(InitPackage {
254:             id: qualified_id(package),
255:             version: versions[&package.id].clone(),
256:             bin_names,
257:             cargo_bin_names,
258:             unsupported_bin_ecosystems: unsupported_bin_ecosystems.into_iter().collect(),
259:             last_tag: tags.last_tag(&package.id).map(|tag| tag.name.clone()),
260:             publish_to: package
261:                 .publish_to
262:                 .iter()
263:                 .map(|target| target.config_str().to_owned())
264:                 .filter(|target| target != PublishTarget::None.config_str())
265:                 .collect(),
266:             platform: is_platform_package(package),
267:         });
268:     }
269:     packages.sort_by(|a, b| a.id.cmp(&b.id));
270:     let ecosystems = workspace
271:         .graph
272:         .packages()
273:         .flat_map(|package| package.canonical_manifests())
274:         .map(|manifest| manifest.ecosystem())
275:         .collect();
276:     // Counts attached platform packages too: they never get their own `packages` entry,
277:     // so scanning canonical manifests alone finds only co-located ones.
278:     let has_platform_packages = workspace
279:         .graph
280:         .packages()
281:         .any(|package| is_platform_package(package) || workspace.identity.platforms_of(&package.id).next().is_some());
283:     let matrix = crate::commands::matrix::matrix(&workspace, &crate::commands::matrix::MatrixOptions::default())?;
284:     let has_kind = |kind| matrix.platform_targets.values().any(|group| group.kind == kind);
286:     Ok(InitFacts {
287:         ecosystems,
288:         packages,
289:         has_platform_packages,
290:         has_napi_targets: has_kind(callisto_model::PlatformTargetKind::Napi),
291:         has_maturin_targets: has_kind(callisto_model::PlatformTargetKind::Maturin),
292:         ..templates_only
293:     })
294: }
296: /// One tag convention a package's existing tags follow.
297: struct TagMatch {
298:     convention: &'static str,
299:     template: String,
300:     tags: Vec<String>,
301: }
303: /// Matches each package's tags against the candidate conventions; returns the non-default ones to write.
304: fn detect_tag_templates<R: CommandRunner, D: DependencyResolver>(
305:     workspace: &Workspace<'_, R, D>,
306: ) -> Result<BTreeMap<String, String>, GraphError> {
307:     let all_tags = crate::tags::fetch_all_tags(workspace.git_access())?;
308:     let mut matches: BTreeMap<String, Vec<TagMatch>> = BTreeMap::new();
309:     for package in workspace
310:         .graph
311:         .packages()
312:         .filter(|package| !is_platform_package(package))
313:     {
314:         let grammar = package.version_grammar()?;
315:         for convention in TAG_CONVENTIONS {
316:             let rendered = if convention == DEFAULT_TAG_CONVENTION {
317:                 TagTemplate::default_for(&package.id).as_str()
318:             } else {
319:                 convention.replace("{name}", package.id.name())
320:             };
321:             let Ok(template) = TagTemplate::parse(&rendered) else {
322:                 continue;
323:             };
324:             // A leading digit keeps `{name}-{version}` from claiming `{name}-v1.0.0` under PEP 440.
325:             let tags: Vec<String> = all_tags
326:                 .iter()
327:                 .filter(|tag| {
328:                     template.extract_version_str(tag).is_some_and(|version| {
329:                         version.starts_with(|c: char| c.is_ascii_digit()) && Version::parse(version, grammar).is_ok()
330:                     })
331:                 })
332:                 .cloned()
333:                 .collect();
334:             if !tags.is_empty() {
335:                 matches.entry(qualified_id(package)).or_default().push(TagMatch {
336:                     convention,
337:                     template: rendered,
338:                     tags,
339:                 });
340:             }
341:         }
342:     }
344:     let shared: Vec<String> = matches
345:         .iter()
346:         .filter(|(_, found)| found.iter().any(|found| found.convention == SHARED_TAG_CONVENTION))
347:         .map(|(package, _)| package.clone())
348:         .collect();
349:     if shared.len() > 1 {
350:         return Err(GraphError::InitSharedVersionTag { packages: shared });
351:     }
353:     let mut templates = BTreeMap::new();
354:     for (package, found) in matches {
355:         match found.as_slice() {
356:             [only] => {
357:                 if only.convention != DEFAULT_TAG_CONVENTION {
358:                     templates.insert(package, only.template.clone());
359:                 }

content.content:
360:             }
361:             _ => {
362:                 return Err(GraphError::InitTagTemplateAmbiguous {
363:                     package,
364:                     matches: found
365:                         .iter()
366:                         .map(|found| format!("`{}` ({})", found.template, found.tags.join(", ")))
367:                         .collect(),
368:                 })
369:             }
370:         }
371:     }
372:     Ok(templates)
373: }
375: /// Renders `callisto.toml` from the answers: only answered intent and tag continuity, never defaults.
376: pub fn render_config(facts: &InitFacts, answers: &InitAnswers) -> String {
377:     use toml_edit::{value, Array, ArrayOfTables, DocumentMut, Item, Table};
379:     let mut doc = DocumentMut::new();
380:     if answers.versioning == Versioning::Fixed {
381:         let members: Array = facts
382:             .packages
383:             .iter()
384:             .filter(|package| !package.platform)
385:             .map(|package| package.id.as_str())
386:             .collect();
387:         if !members.is_empty() {
388:             let mut group = Table::new();
389:             group["name"] = value("all");
390:             group["members"] = value(members);
391:             let mut groups = ArrayOfTables::new();
392:             groups.push(group);
393:             doc["fixed-group"] = Item::ArrayOfTables(groups);
394:         }
395:     }
396:     let mut rules: BTreeMap<&str, Table> = BTreeMap::new();
397:     for (package, template) in &facts.tag_templates {
398:         rules.entry(package).or_default()["tag-template"] = value(template.as_str());
399:     }
400:     let product = answers
401:         .binaries
402:         .as_ref()
403:         .and_then(|release| facts.packages.iter().find(|package| package.id == release.product));
404:     if let Some(product) = product {
405:         // Artifact slots derive only for a product that publishes to github-release.
406:         let publish_to: Array = product
407:             .publish_to
408:             .iter()
409:             .map(String::as_str)
410:             .chain([PublishTarget::GitHubRelease.config_str()])
411:             .collect();
412:         rules.entry(&product.id).or_default()["publish-to"] = value(publish_to);
413:     }
414:     if !rules.is_empty() {
415:         let mut tables = ArrayOfTables::new();
416:         for (package, rule) in rules {
417:             let mut table = Table::new();
418:             table["match"] = value(package);
419:             table.extend(rule);
420:             tables.push(table);
421:         }
422:         doc["package"] = Item::ArrayOfTables(tables);
423:     }
424:     if let Some(release) = &answers.binaries {
425:         let bin_names = product
426:             .map(|package| package.cargo_bin_names.as_slice())
427:             .unwrap_or_default();
428:         let mut table = Table::new();
429:         table["product-package"] = value(release.product.as_str());
430:         table["forge-repository"] = value(release.forge_repository.as_slug());
431:         let mut artifacts = ArrayOfTables::new();
432:         for target in &release.targets {
433:             for bin in bin_names {
434:                 let extension = if target.contains("windows") { "zip" } else { "tar.gz" };
435:                 let mut artifact = Table::new();
436:                 artifact["package"] = value(release.product.as_str());
437:                 artifact["target"] = value(target.as_str());
438:                 artifact["asset-name"] = value(format!("{bin}-{target}.{extension}"));
439:                 artifacts.push(artifact);
440:             }
441:         }
442:         table["artifact"] = Item::ArrayOfTables(artifacts);
443:         doc["release"] = Item::Table(table);
444:     }
445:     let body = doc.to_string();
446:     if body.is_empty() {
447:         CONFIG_HEADER.to_owned()
448:     } else {
449:         format!("{CONFIG_HEADER}\n{body}")
450:     }
451: }
453: fn resolve_config_text(root: &Path, text: &str) -> Result<ResolvedConfig, GraphError> {
454:     let raw = toml::from_str::<RawConfig>(text).map_err(|error| ConfigError::ParseToml {
455:         path: root.join("callisto.toml"),
456:         message: error.to_string(),
457:     })?;
458:     Ok(crate::config::resolve(root, raw)?)
459: }
461: /// The first release `config` would produce, from the plan behind `release --dry-run`.
462: ///
463: /// # Errors
464: ///
465: /// `config` fails to resolve, or the release plan cannot be derived.
466: pub fn preview<L: ProjectLocator, R: CommandRunner>(
467:     facts: &InitFacts,
468:     config: &str,
469:     locator: &L,
470:     runner: &R,
471: ) -> Result<Option<LocalReleasePlan>, GraphError> {
472:     let resolved = resolve_config_text(&facts.root, config)?;
473:     let workspace = Workspace::load_with_config(facts.root.clone(), resolved, locator, runner)?;
474:     plan_workspace_release(&workspace, &[], LocalReleaseSource::Preview)
475: }
477: /// Parses a forge repository answer, which the release plan requires to be `origin`'s GitHub repository.
478: ///
479: /// # Errors
480: ///
481: /// `value` is not a GitHub `owner/repo`, or is not `origin`'s.
482: pub fn forge_repository(facts: &InitFacts, value: &str) -> Result<GitHubRepository, GraphError> {
483:     let repository = GitHubRepository::parse(value.trim()).map_err(|error| GraphError::InitInvalidForgeRepository {
484:         value: value.to_owned(),
485:         reason: error.to_string(),
486:     })?;
487:     if facts.origin_repository.as_ref() != Some(&repository) {
488:         return Err(GraphError::InitForgeRepositoryMismatch {
489:             configured: repository.as_slug(),
490:             origin: facts.origin.clone().unwrap_or_else(|| "none".to_owned()),
491:         });
492:     }
493:     Ok(repository)
494: }
496: /// Validates artifact target triples.
497: ///
498: /// # Errors
499: ///
500: /// An empty or repeated triple.
501: pub fn validate_targets(targets: &[String]) -> Result<Vec<String>, GraphError> {
502:     let mut seen = BTreeSet::new();
503:     for target in targets {
504:         let invalid = |reason| GraphError::InitInvalidTargetTriple {
505:             triple: target.clone(),
506:             reason,
507:         };
508:         if target.trim().is_empty() {
509:             return Err(invalid("it is empty"));
510:         }
511:         if !seen.insert(target.as_str()) {
512:             return Err(invalid("it is given more than once"));
513:         }
514:     }
515:     Ok(targets.to_vec())
516: }
518: /// Files `init` writes, or would write under `--dry-run`: `callisto.toml`, `.changeset/README.md`
519: /// unless it already exists, and the release workflow when `workflow` is `true`. Reads current
520: /// disk state, so callers compute this before writing anything.
521: ///
522: /// # Errors
523: ///
524: /// The README's existence cannot be determined.
525: pub fn init_files(root: &Path, workflow: bool) -> Result<Vec<PathBuf>, GraphError> {
526:     let readme = root.join(".changeset/README.md");
527:     let mut files = vec![root.join("callisto.toml")];
528:     if !callisto_model::strict_fs::exists(&readme).map_err(io_err(&readme))? {
529:         files.push(readme);
530:     }
531:     if workflow {
532:         files.push(workflow_path(root));
533:     }
534:     Ok(files)
535: }
537: /// Writes `callisto.toml` and, when absent, `.changeset/README.md`.
538: ///
539: /// # Errors
540: ///
541: /// `callisto.toml` already exists, or a write fails.
542: pub fn write(root: &Path, config: &str, permit: &ApplyPermit) -> Result<InitReport, GraphError> {
543:     ensure_uninitialized(root)?;
544:     let config_path = root.join("callisto.toml");
545:     let files = init_files(root, false)?;
546:     callisto_model::atomic::atomic_write(&config_path, config, permit).map_err(io_err(&config_path))?;
547:     write_changeset_readme(root, permit)?;
548:     Ok(InitReport {
549:         schema_version: SCHEMA_VERSION,
550:         initialized: true,
551:         config_path,
552:         config: config.to_owned(),
553:         files,
554:         diagnostics: Vec::new(),
555:     })
556: }
558: /// Creates `.changeset/README.md` unless it already exists.
559: ///
560: /// # Errors
561: ///
562: /// A directory or file write fails.
563: pub fn write_changeset_readme(root: &Path, permit: &ApplyPermit) -> Result<(), GraphError> {
564:     let readme = root.join(".changeset/README.md");
565:     if callisto_model::strict_fs::exists(&readme).map_err(io_err(&readme))? {
566:         return Ok(());
567:     }
568:     let changeset_dir = root.join(".changeset");
569:     std::fs::create_dir_all(&changeset_dir).map_err(io_err(&changeset_dir))?;
570:     callisto_model::atomic::atomic_write(&readme, CHANGESET_README, permit).map_err(io_err(&readme))
571: }
573: /// `@changesets/cli` `config.json` keys callisto never reads, and the callisto.toml construct
574: /// that replaces each one, when one exists.
575: const CHANGESETS_CONFIG_KEYS: [(&str, Option<&str>); 6] = [
576:     ("fixed", Some("[[fixed-group]]")),
577:     ("linked", None),
578:     ("ignore", None),
579:     ("access", None),
580:     ("baseBranch", None),
581:     ("updateInternalDependencies", None),
582: ];
584: /// Warns, per key, about every `.changeset/config.json` key callisto ignores.
585: ///
586: /// callisto never translates this file; a present, unhonoured key is silently inert otherwise.
587: /// Returns no diagnostics when the file is absent or is not a JSON object.
588: pub fn changesets_config_diagnostics(root: &Path) -> Vec<Diagnostic> {
589:     let path = root.join(".changeset/config.json");
590:     let Ok(text) = std::fs::read_to_string(&path) else {
591:         return Vec::new();
592:     };
593:     let Ok(serde_json::Value::Object(config)) = serde_json::from_str(&text) else {
594:         return Vec::new();
595:     };
596:     CHANGESETS_CONFIG_KEYS
597:         .iter()
598:         .filter(|(key, _)| config.contains_key(*key))
599:         .map(|(key, equivalent)| {
600:             let message = match equivalent {
601:                 Some(equivalent) => {
602:                     format!("`.changeset/config.json` key `{key}` is not honoured; use {equivalent} instead")
603:                 }
