361:             format!("SOURCE_DATE_EPOCH={source_date_epoch}"),
362:             interpreter.to_string(),
363:             "-m".to_string(),
364:             "build".to_string(),
365:             "--sdist".to_string(),
366:             "--wheel".to_string(),
367:             "--outdir".to_string(),
368:             outdir.to_string_lossy().into_owned(),
369:         ],
370:         cwd: workspace_root.join(package_dir),
371:     })
372: }
374: /// `twine upload` of exactly `files`, never a glob or `--skip-existing`, which skips by name without comparing bytes.
375: pub fn pypi_upload_argv(workspace_root: &Path, package_dir: &Path, index: Option<&str>, files: &[PathBuf]) -> Argv {
376:     let mut args = vec!["upload".to_string()];
377:     if let Some(index) = index {
378:         args.push("--repository-url".to_string());
379:         args.push(index.to_string());
