30: /// Identity used to merge the same underlying change across every package it
31: /// bumps, instead of repeating its rendered text once per package. A shared
32: /// `.changeset/*.md` file's `summary` is copied verbatim into every package
33: /// it names (fan-out) -- correct and desirable for each
34: /// package's own standalone `CHANGELOG.md`, but exactly the duplication that
35: /// makes a multi-package PR body hard to read in one sitting.
36: #[derive(Clone, PartialEq, Eq, Hash)]
37: enum ChangeGroupKey {
38:     Changeset(String),
39:     Commit(String),
40:     PeerEscalation(PackageId, String),
41:     DependencyUpdate(PackageId, String),
42:     /// Never merged across packages: one `ChangelogWrite` per package whose
43:     /// `render_section` failed (e.g. an empty or `Severity::None` entry) or
44:     /// was entirely absent, falling back to `bump.reason`-derived text --
45:     /// package-specific by construction, so each gets its own slot.
46:     Fallback(usize),
47: }
49: struct ChangeGroup {
50:     /// Rendered once, from the first (and, for real changesets, only
51:     /// possible) occurrence -- every member's copy is byte-identical by
52:     /// construction for `Changeset`/`Commit` keys.
53:     body: String,
54:     /// `(package, this entry's own severity)` -- deliberately the entry's
55:     /// severity, not the package's overall post-cascade `bump.severity`,
56:     /// since one package can carry several entries at different severities.
57:     members: Vec<(PackageId, Severity)>,
58:     /// `Fallback` groups render like a standalone per-package block (their
59:     /// one member's name becomes the heading); real changes render as
60:     /// "<key> -- affects: pkg, pkg".
61:     is_fallback: bool,
62: }
64: impl ChangeGroup {
65:     fn has_major(&self) -> bool {
66:         self.max_severity() == Severity::Major
67:     }
69:     /// Drives major-first ordering in the change list, matching the summary
70:     /// table's own sort exactly rather than a coarser major-vs-not split --
71:     /// otherwise a patch-only and a minor-only change could render in
72:     /// declaration order relative to each other while the table (correctly)
73:     /// puts the minor one first.
74:     fn max_severity(&self) -> Severity {
75:         self.members
76:             .iter()
77:             .map(|(_, severity)| *severity)
78:             .max()
79:             .unwrap_or(Severity::None)
80:     }
81: }
83: /// Renders one changelog entry's bullet text in isolation, mirroring
84: /// `crate::changelog::render_section`'s per-source formatting exactly
85: /// (minus its cross-entry `DependencyUpdate` batching, which does not apply
86: /// once entries are regrouped across packages by shared identity instead of
87: /// by owning package). Returns `None` for a `Changeset`/`Commit`-equivalent
88: /// source with nothing to say (matching `render_section`'s own
89: /// empty-summary skip).
90: fn render_entry_text(source: &ChangeSource) -> Option<String> {
91:     match source {
92:         ChangeSource::Changeset { summary, .. } => indent_changeset_summary(summary),
93:         ChangeSource::Commit { subject, sha } => Some(format!("{subject} ({})", sha.short())),
94:         ChangeSource::DependencyUpdate { dependency, to, .. } => {
95:             Some(format!("`{}` → `{}`", dependency.display_name(), to.render()))
96:         }
97:         ChangeSource::PeerEscalation { dependency, to } => Some(format!(
98:             "Peer dependency `{}` requires `{}`",
99:             dependency.display_name(),
100:             to.render()
101:         )),
102:         // GroupUnion/NewGroupMember carry no content of their own beyond
103:         // "this package moved because its group did" -- already visible in
104:         // the summary table's Reason column, so they are deliberately
105:         // excluded from `What's Changing` entirely rather than rendered as
106:         // a redundant one-line block (see `change_group_key`'s matching arm
107:         // and the bystander-note logic in `render_pr_body_from_plan`).
108:         ChangeSource::GroupUnion { .. } | ChangeSource::NewGroupMember { .. } => None,
109:     }
110: }
112: fn change_group_key(source: &ChangeSource) -> Option<ChangeGroupKey> {
113:     match source {
114:         ChangeSource::Changeset { filename, .. } => Some(ChangeGroupKey::Changeset(filename.clone())),
115:         ChangeSource::Commit { sha, .. } => Some(ChangeGroupKey::Commit(sha.as_str().to_string())),
116:         ChangeSource::PeerEscalation { dependency, to } => Some(ChangeGroupKey::PeerEscalation(
117:             dependency.clone(),
118:             to.render().to_string(),
119:         )),
120:         ChangeSource::DependencyUpdate { dependency, to, .. } => Some(ChangeGroupKey::DependencyUpdate(
121:             dependency.clone(),
122:             to.render().to_string(),
123:         )),
124:         ChangeSource::GroupUnion { .. } | ChangeSource::NewGroupMember { .. } => None,
125:     }
126: }
128: /// A short, stable label for a change group's `<summary>` -- derived from
129: /// its identity (a changeset filename, a commit, a dependency bump), never
130: /// from sniffing the free-text body, so it stays predictable even when a
131: /// changeset's summary doesn't start with a bolded headline.
132: fn change_group_label(key: &ChangeGroupKey) -> String {
133:     match key {
134:         ChangeGroupKey::Changeset(filename) => {
135:             format!("`{}`", filename.strip_suffix(".md").unwrap_or(filename))
136:         }
137:         ChangeGroupKey::Commit(sha) => format!("Commit `{}`", &sha[..sha.len().min(7)]),
138:         ChangeGroupKey::PeerEscalation(dep, to) => {
139:             format!("Peer dependency `{}` → `{}`", dep.display_name(), to)
140:         }
141:         ChangeGroupKey::DependencyUpdate(dep, to) => format!("Dependency `{}` → `{}`", dep.display_name(), to),
142:         ChangeGroupKey::Fallback(_) => unreachable!("Fallback groups render via their sole member, not this label"),
143:     }
144: }
146: /// Text for a package whose `ChangelogWrite` is absent or failed to render
147: /// (e.g. an empty or `Severity::None` entry) -- derived from `bump.reason`
148: /// instead. Package-specific by construction (a `BumpReason` describes one
149: /// package's own severity computation), so never merged across packages.
150: fn fallback_reason_text(bump: &crate::plan::PlannedBump) -> String {
151:     match &bump.reason {
152:         Some(reason) => match reason {
153:             callisto_model::BumpReason::Changeset { changesets } => {
154:                 format!("- Associated changesets: `{}`\n", changesets.join("`, `"))
155:             }
156:             callisto_model::BumpReason::Cascade {
157:                 via,
158:                 spec,
159:                 dependency_to,
160:                 ..
161:             } => {
162:                 format!(
163:                     "- Automatic dependency cascade triggered by `{}` (spec `{}` target `{}`).\n",
164:                     via.display_name(),
165:                     spec,
166:                     dependency_to.render()
167:                 )
168:             }
169:             callisto_model::BumpReason::PeerEscalation { via, spec } => {
170:                 format!(
171:                     "- Peer dependency escalation triggered by `{}` (spec `{}`).\n",
172:                     via.display_name(),
173:                     spec
174:                 )
175:             }
176:             callisto_model::BumpReason::FixedGroupUnion { group } => {
177:                 format!("- Fixed group synchronization for group `{}`.\n", group.as_str())
178:             }
179:             callisto_model::BumpReason::LinkedGroupUnion { group } => {
180:                 format!("- Linked group version alignment for group `{}`.\n", group.as_str())
181:             }
182:             callisto_model::BumpReason::Inference { commits, .. } => {
183:                 format!("- Inferred from {commits} commit(s) since the last release.\n")
184:             }
185:             callisto_model::BumpReason::PreRelease { tag } => {
186:                 format!("- Pre-release finalization (tag `{tag}`).\n")
187:             }
188:             callisto_model::BumpReason::NewGroupMember { group } => {
189:                 format!("- New member of group `{}`.\n", group.as_str())
190:             }
191:             _ => "_No changelog entries available._\n".to_string(),
192:         },
193:         None => "_No changelog entries available._\n".to_string(),
194:     }
195: }
197: pub fn compose_pr_body<R: CommandRunner, D: DependencyResolver, I: SeverityInference>(
198:     ws: &Workspace<'_, R, D>,
199:     inference: &I,
200:     opts: &PrBodyOptions,
201: ) -> Result<ComposePrBodyReport, GraphError> {
202:     let plan = plan_version(ws, inference, &crate::commands::version::VersionOptions::default())?;
203:     render_pr_body_from_plan(&plan, opts)
204: }
206: pub fn render_pr_body_from_plan(
207:     plan: &crate::plan::VersionPlan,
208:     opts: &PrBodyOptions,
209: ) -> Result<ComposePrBodyReport, GraphError> {
210:     let mut body = String::new();
212:     // Preserve custom user notes above ## Release Preview if an existing body was passed
213:     if let Some(ref existing) = opts.existing_body
214:         && let Some((prefix, _)) = existing.split_once("## Release Preview")
215:         && !prefix.trim().is_empty()
216:     {
217:         body.push_str(prefix);
218:         if !prefix.ends_with('\n') {
219:             body.push('\n');
220:         }
221:     }
223:     body.push_str("## Release Preview\n\n");
224:     body.push_str("This automated PR was generated by [Callisto](https://github.com/orin-dx/callisto). Merging this PR will publish the updated packages to their release targets.\n\n");
226:     if plan.bumps.is_empty() {
227:         body.push_str("> [!NOTE]\n");
228:         body.push_str("> **No pending changesets found.** Workspace packages are currently up to date.\n\n");
229:         let branch = opts.branch.as_deref().unwrap_or("callisto/version-packages");
230:         body.push_str("<details>\n<summary><b>Release Workflow Instructions</b></summary>\n\n");
231:         body.push_str("- **Merging this PR**: Merging into `main` will automatically publish all updated packages to their release registries.\n");
232:         body.push_str("- **Adding more changesets**: If additional changesets are pushed to `main`, Callisto will automatically re-calculate and update this PR.\n");
233:         body.push_str(&format!(
234:             "- **Manual edits**: You can make manual adjustments directly on the `{}` branch if needed.\n\n",
235:             branch
236:         ));
237:         body.push_str("</details>\n");
238:         return Ok(ComposePrBodyReport {
239:             schema_version: SCHEMA_VERSION,
240:             body,
241:             diagnostics: Vec::new(),
242:         });
243:     }
245:     // 1. Executive Summary Table
246:     body.push_str("### 📊 Release Summary\n\n");
247:     body.push_str("| Package | Ecosystem | Current | Target | Bump | Reason |\n");
248:     body.push_str("| :--- | :--- | :--- | :--- | :--- | :--- |\n");
250:     // Major-first: a reviewer's real question is "is anything breaking,"
251:     // and that must be answerable from the top of the table without
252:     // scanning every row for a package whose name happens to sort late.
253:     // Stable, so ties keep their original (plan) relative order.
254:     let mut sorted_bumps: Vec<&crate::plan::PlannedBump> = plan.bumps.iter().collect();
255:     sorted_bumps.sort_by_key(|bump| std::cmp::Reverse(bump.severity));
257:     for bump in &sorted_bumps {
258:         let eco = bump.package.ecosystem().map(|e| e.prefix()).unwrap_or("core");
260:         let reason_str = match &bump.reason {
261:             Some(callisto_model::BumpReason::Changeset { changesets }) => {
262:                 format!("Changeset (`{}`)", changesets.join("`, `"))
263:             }
264:             Some(callisto_model::BumpReason::Cascade { via, .. }) => {
265:                 format!("Cascade from `{}`", via.display_name())
266:             }
267:             Some(callisto_model::BumpReason::PeerEscalation { via, .. }) => {
268:                 format!("Peer escalation from `{}`", via.display_name())
269:             }
270:             Some(callisto_model::BumpReason::FixedGroupUnion { group }) => {
271:                 format!("Fixed group `{}`", group.as_str())
272:             }
273:             Some(callisto_model::BumpReason::LinkedGroupUnion { group }) => {
274:                 format!("Linked group `{}`", group.as_str())
275:             }
276:             Some(callisto_model::BumpReason::Inference { commits, .. }) => {
277:                 format!("Inferred ({commits} commits)")
278:             }
279:             Some(callisto_model::BumpReason::PreRelease { tag }) => {
280:                 format!("Prerelease (`{tag}`)")
281:             }
282:             Some(callisto_model::BumpReason::NewGroupMember { group }) => {
283:                 format!("New member (`{}`)", group.as_str())
284:             }
285:             _ => "Package bump".to_string(),
286:         };
288:         body.push_str(&format!(
289:             "| `{}` | `{}` | `{}` | **`{}`** | {} `{}` | {} |\n",
290:             bump.package.display_name(),
291:             eco,
292:             bump.from.render(),
293:             bump.to.render(),
294:             severity_emoji(bump.severity),
295:             bump.severity,
296:             reason_str
297:         ));
298:     }
300:     body.push('\n');
302:     // 2. Alert Callouts
303:     body.push_str(&review_callout(&plan.bumps));
305:     // 3. What's Changing -- grouped by underlying change, not by package, so
306:     // a changeset naming several packages (fan-out) renders once
307:     // instead of once per package it touches.
308:     body.push_str("### 📦 What's Changing\n\n");
310:     // PERF: build a map once so each lookup inside the loop is O(1)
311:     // instead of O(N) (the previous changelog_writes().find() call).
312:     let changelog_write_map: HashMap<_, _> = plan.changelog_writes.iter().map(|w| (&w.input.package, w)).collect();
314:     let mut groups: IndexMap<ChangeGroupKey, ChangeGroup> = IndexMap::new();
315:     let mut bystanders: Vec<PackageId> = Vec::new();
316:     let mut fallback_counter = 0usize;
318:     for bump in &plan.bumps {
319:         let matching_write = changelog_write_map.get(&bump.package).copied();
321:         let section_ok = matching_write.is_some_and(|w| crate::changelog::render_section(&w.input).is_ok());
323:         if section_ok {
324:             let entries = &matching_write
325:                 .expect("section_ok implies a matching write")
326:                 .input
327:                 .entries;
328:             let mut has_substantive_entry = false;
330:             for entry in entries {
331:                 let Some(key) = change_group_key(&entry.source) else {
332:                     continue; // GroupUnion/NewGroupMember: no content of its own, see render_entry_text
333:                 };
334:                 let Some(text) = render_entry_text(&entry.source) else {
335:                     continue; // empty summary, matches render_section's own skip
336:                 };
337:                 has_substantive_entry = true;
338:                 groups
339:                     .entry(key)
340:                     .or_insert_with(|| ChangeGroup {
341:                         body: text,
342:                         members: Vec::new(),
343:                         is_fallback: false,
344:                     })
345:                     .members
346:                     .push((bump.package.clone(), entry.severity));
347:             }
349:             if !has_substantive_entry {
350:                 bystanders.push(bump.package.clone());
351:             }
352:         } else {
353:             let fallback_body = fallback_reason_text(bump);
354:             fallback_counter += 1;
355:             groups.insert(
356:                 ChangeGroupKey::Fallback(fallback_counter),
357:                 ChangeGroup {
358:                     body: fallback_body,
359:                     members: vec![(bump.package.clone(), bump.severity)],
360:                     is_fallback: true,
361:                 },
362:             );
363:         }
364:     }
366:     if !bystanders.is_empty() {
367:         let names: Vec<String> = bystanders.iter().map(|p| format!("`{}`", p.display_name())).collect();
368:         body.push_str(&format!(
369:             "_Also bumped with no direct change of their own (released together via a fixed/linked group): {}._\n\n",
370:             names.join(", ")
371:         ));
372:     }
374:     body.push_str(&format!(
375:         "**{} change(s) across {} package(s):**\n\n",
376:         groups.len(),
377:         plan.bumps.len()
378:     ));
380:     // Major-first, same rationale as the summary table: a change containing
381:     // a breaking bump must be the first thing a reviewer sees, not wherever
382:     // it happens to fall by first-encountered-package order. Stable, so
383:     // ties keep their original order.
384:     let mut sorted_groups: Vec<(&ChangeGroupKey, &ChangeGroup)> = groups.iter().collect();
385:     sorted_groups.sort_by_key(|(_, group)| std::cmp::Reverse(group.max_severity()));
387:     for (key, group) in sorted_groups {
388:         let inner_open = if group.has_major() { " open" } else { "" };
390:         if group.is_fallback {
391:             let (package, severity) = &group.members[0];
392:             body.push_str(&format!(
393:                 "<details{}>\n<summary><b>{}</b> ({} {})</summary>\n\n",
394:                 inner_open,
395:                 package.display_name(),
396:                 severity_emoji(*severity),
397:                 severity
398:             ));
399:         } else {
400:             let affected: Vec<String> = group
401:                 .members
402:                 .iter()
403:                 .map(|(package, _)| format!("<code>{}</code>", package.display_name()))
404:                 .collect();
405:             body.push_str(&format!(
406:                 "<details{}>\n<summary><b>{}</b> — affects {}</summary>\n\n",
407:                 inner_open,
408:                 change_group_label(key),
409:                 affected.join(", ")
410:             ));
411:         }
413:         body.push_str(&group.body);
414:         if !group.body.ends_with('\n') {
415:             body.push('\n');
416:         }
417:         body.push_str("\n</details>\n\n");
418:     }
420:     // 4. Instructions Footer
421:     let branch = opts.branch.as_deref().unwrap_or("callisto/version-packages");
422:     body.push_str("<details>\n<summary><b>Release Workflow Instructions</b></summary>\n\n");
423:     body.push_str("- **Merging this PR**: Merging into `main` will automatically publish all updated packages to their release registries.\n");
424:     body.push_str("- **Adding more changesets**: If additional changesets are pushed to `main`, Callisto will automatically re-calculate and update this PR.\n");
425:     body.push_str(&format!(
426:         "- **Manual edits**: You can make manual adjustments directly on the `{}` branch if needed.\n\n",
427:         branch
428:     ));
429:     body.push_str("</details>\n");
431:     Ok(ComposePrBodyReport {
432:         schema_version: SCHEMA_VERSION,
433:         body,
434:         diagnostics: Vec::new(),
435:     })
436: }
438: /// The callout that opens the release PR body. Claims backward compatibility only for stable versions: below 1.0.0 a
439: /// minor bump is where breaking changes go, so it cannot be called compatible.
440: fn review_callout(bumps: &[crate::plan::PlannedBump]) -> String {
441:     if bumps.iter().any(|bump| bump.severity == Severity::Major) {
442:         return "> [!WARNING]\n> **Major Version Bumps Detected**: This release contains major breaking changes. Review \
443:                 the changes below before merging.\n\n"
444:             .to_owned();
445:     }
446:     let pre_one_minor = bumps
447:         .iter()
448:         .any(|bump| bump.severity == Severity::Minor && bump.from.render().starts_with("0."));
449:     let verdict = if pre_one_minor {
450:         "Minor bumps below 1.0.0 can include breaking changes, so read the changes below before merging."
451:     } else {
452:         "All changes are backward compatible."
453:     };
454:     format!(
455:         "> [!NOTE]\n> **{} package(s)** queued for versioning. {verdict}\n\n",
456:         bumps.len()
457:     )
458: }

