438: /// The callout that opens the release PR body. Claims backward compatibility only for stable versions: below 1.0.0 a
439: /// minor bump is where breaking changes go, so it cannot be called compatible.
440: fn review_callout(bumps: &[crate::plan::PlannedBump]) -> String {
441:     if bumps.iter().any(|bump| bump.severity == Severity::Major) {
442:         return "> [!WARNING]\n> **Major Version Bumps Detected**: This release contains major breaking changes. Review \
443:                 the changes below before merging.\n\n"
444:             .to_owned();
445:     }
446:     let pre_one_minor = bumps
447:         .iter()
448:         .any(|bump| bump.severity == Severity::Minor && bump.from.render().starts_with("0."));
449:     let verdict = if pre_one_minor {
450:         "Minor bumps below 1.0.0 can include breaking changes, so read the changes below before merging."
451:     } else {
452:         "All changes are backward compatible."
453:     };
454:     format!(
455:         "> [!NOTE]\n> **{} package(s)** queued for versioning. {verdict}\n\n",
456:         bumps.len()
457:     )
458: }

