18: /// Computes one [`ReleasePackageId`] per canonical manifest, ecosystem-qualified
19: /// against `package`'s name.
20: ///
21: /// This is the single derivation of release package identity shared by every
22: /// site that computes or verifies release authority: [`derive_release_decision`],
23: /// [`derive_release_commit_decision`], and `release::derive_release_inputs`.
24: /// Per this module's own established lesson (see the doc comment on
25: /// [`derive_release_commit_decision`]), independently reimplementing this
26: /// mapping at each call site is exactly the kind of duplicated derivation
27: /// that drifts -- so it lives here once instead.
28: pub(crate) fn release_package_ids(
29:     identity: &crate::IdentityIndex,
30:     package: &Package,
31: ) -> Result<Vec<ReleasePackageId>, GraphError> {
32:     package
33:         .canonical_manifests()
34:         .map(|manifest| {
35:             let ecosystem = manifest.ecosystem();
36:             // A dual-manifest package's manifests may declare different names.
37:             let name = identity
38:                 .native_name(&package.id, ecosystem)
39:                 .unwrap_or(package.id.name());
40:             ReleasePackageId::new(ecosystem, name)
41:         })
42:         .collect::<Result<Vec<_>, _>>()
43:         .map_err(GraphError::from)
44: }
46: /// Derives the durable roster from a freshly computed version plan.
47: ///
48: /// The caller supplies the plan from the same workspace observation; this
49: /// function never inspects a caller-provided release roster.
50: pub fn derive_release_decision<R: callisto_model::CommandRunner, D: DependencyResolver>(
51:     workspace: &Workspace<'_, R, D>,
52:     plan: &VersionPlan,
53: ) -> Result<ReleaseDecisionV1, GraphError> {
54:     let mut package_ids = std::collections::BTreeMap::new();
55:     for package in workspace.graph.packages() {
56:         let ids = release_package_ids(&workspace.identity, package)?;
57:         package_ids.insert(package.id.clone(), ids);
58:     }
60:     let mut entries = Vec::new();
61:     for bump in &plan.bumps {
62:         // `plan` is contractually derived from this same workspace
63:         // observation (see doc comment above), so every bump's package must
64:         // already be a key here -- a miss means the plan/workspace pairing
65:         // itself is inconsistent, not a recoverable operator condition.
66:         let ids = package_ids
67:             .get(&bump.package)
68:             .ok_or_else(|| GraphError::ReleaseInvariant {
69:                 detail: format!(
70:                     "version plan references package `{}`, which is absent from this workspace observation",
71:                     bump.package.display_name()
72:                 ),
73:             })?;
74:         for id in ids {
75:             entries.push(ReleaseDecisionEntry {
76:                 package: id.clone(),
77:                 target_version: bump.to.clone(),
78:                 reasons: vec![reason_from_bump(
79:                     &workspace.graph,
80:                     &bump.package,
81:                     id,
82:                     bump.reason.as_ref(),
83:                     &package_ids,
84:                 )?],
85:             });
86:         }
87:     }
88:     ReleaseDecisionV1::new(entries).map_err(GraphError::from)
89: }
91: /// Derives a durable decision for explicit, exact release identities.
92: ///
93: /// A linked group is one release unit: selecting any member includes every
94: /// member of that linked group which the version plan selected. All other
95: /// packages remain outside the authority boundary. The caller must pass
96: /// ecosystem-qualified [`ReleasePackageId`] values; this function never uses
97: /// `PackageId::matches`, whose bare-name wildcard semantics are unsuitable
98: /// for release authority.
99: pub fn derive_selected_release_decision<R: callisto_model::CommandRunner, D: DependencyResolver>(
100:     workspace: &Workspace<'_, R, D>,
101:     plan: &VersionPlan,
102:     selections: &[ReleasePackageId],
103: ) -> Result<ReleaseDecisionV1, GraphError> {
104:     let complete = derive_release_decision(workspace, plan)?;
106:     let mut seen = std::collections::BTreeSet::new();
107:     if let Some(duplicate) = selections.iter().find(|selection| !seen.insert(*selection)) {
108:         return Err(GraphError::ReleaseSelectionInvalid {
109:             package: duplicate.clone(),
110:             reason: ReleaseSelectionInvalidReason::Duplicate,
111:         });
112:     }
114:     let selected = selections.iter().collect::<std::collections::BTreeSet<_>>();
115:     for selection in &selected {
116:         let Some(package) = workspace_package(workspace, selection) else {
117:             return Err(GraphError::UnknownPackage {
118:                 id: callisto_model::PackageId::Prefixed {
119:                     ecosystem: selection.ecosystem(),
120:                     name: selection.name().to_string(),
121:                 },
122:             });
123:         };
124:         let reason = if !complete.entries.iter().any(|entry| &entry.package == *selection) {
125:             ReleaseSelectionInvalidReason::NotARelease
126:         } else if package
127:             .publish_to
128:             .iter()
129:             .all(|target| matches!(target, callisto_model::PublishTarget::None))
130:         {
131:             ReleaseSelectionInvalidReason::NoDispatchableTarget
132:         } else {
133:             continue;
134:         };
135:         return Err(GraphError::ReleaseSelectionInvalid {
136:             package: (*selection).clone(),
137:             reason,
138:         });
139:     }
141:     let entries = expand_selection(workspace, complete.entries, &selected);
142:     ReleaseDecisionV1::new(entries).map_err(GraphError::from)
143: }
145: /// Keeps the selected entries plus every entry sharing a fixed or linked group
146: /// with a selection. Both release routes narrow `--package` through this.
147: fn expand_selection<R: callisto_model::CommandRunner, D: DependencyResolver>(
148:     workspace: &Workspace<'_, R, D>,
149:     entries: Vec<ReleaseDecisionEntry>,
150:     selected: &std::collections::BTreeSet<&ReleasePackageId>,
151: ) -> Vec<ReleaseDecisionEntry> {
152:     // A plan-derived entry carries its linked group as a reason.
153:     let reason_groups = entries
154:         .iter()
155:         .filter(|entry| selected.contains(&entry.package))
156:         .flat_map(|entry| entry.reasons.iter())
157:         .filter_map(|reason| match reason {
158:             ReleaseInclusionReason::LinkedGroup { group_id } => Some(group_id.clone()),
159:             _ => None,
160:         })
161:         .collect::<std::collections::BTreeSet<_>>();
162:     // Config membership: a selected member's own reason is often `Changeset` or `UnreleasedVersion`.
163:     let config_groups = selected
164:         .iter()
165:         .flat_map(|selection| release_groups_of(workspace, selection))
166:         .collect::<std::collections::BTreeSet<_>>();
167:     // Selecting one distribution of a package releases all of them, so the shared tag waits for every publish.
168:     let selected_packages = selected
169:         .iter()
170:         .filter_map(|selection| workspace_package(workspace, selection))
171:         .map(|package| package.id.clone())
172:         .collect::<std::collections::BTreeSet<_>>();
173:     entries
174:         .into_iter()
175:         .filter(|entry| {
176:             selected.contains(&entry.package)
177:                 || workspace_package(workspace, &entry.package).is_some_and(|package| selected_packages.contains(&package.id))
178:                 || entry.reasons.iter().any(|reason| {
179:                     matches!(reason, ReleaseInclusionReason::LinkedGroup { group_id } if reason_groups.contains(group_id))
180:                 })
181:                 || release_groups_of(workspace, &entry.package)
182:                     .iter()
183:                     .any(|group| config_groups.contains(group))
184:         })
185:         .collect()
186: }
188: /// Derives the roster of every publishable package whose current version has
189: /// no tag in the canonical [`crate::TagIndex`], each with
190: /// [`ReleaseInclusionReason::UnreleasedVersion`].
191: ///
192: /// A non-empty `selections` restricts the roster to exactly those identities,
193: /// each of which must be unreleased and publishable. `None` means nothing is
194: /// unreleased.
195: pub fn derive_unreleased_decision<R: callisto_model::CommandRunner, D: DependencyResolver>(
196:     workspace: &Workspace<'_, R, D>,
197:     selections: &[ReleasePackageId],
198: ) -> Result<Option<ReleaseDecisionV1>, GraphError> {
199:     derive_release_roster(workspace, selections, &std::collections::BTreeSet::new())
200: }
202: /// [`derive_unreleased_decision`] that also keeps the tagged releases in `resumable`: a tag
203: /// does not prove the rest of the release was observed.
204: pub(crate) fn derive_release_roster<R: callisto_model::CommandRunner, D: DependencyResolver>(
205:     workspace: &Workspace<'_, R, D>,
206:     selections: &[ReleasePackageId],
207:     resumable: &std::collections::BTreeSet<ReleasePackageId>,
208: ) -> Result<Option<ReleaseDecisionV1>, GraphError> {
209:     let versions = workspace.base_versions()?;
210:     let tags = workspace.tags()?;
211:     let mut entries = Vec::new();
212:     for package in workspace.graph.packages() {
213:         if !has_dispatchable_target(package) {
214:             continue;
215:         }
216:         let version = versions.get(&package.id).ok_or_else(|| GraphError::ReleaseInvariant {
217:             detail: format!("package `{}` has no base version", package.id.display_name()),
218:         })?;
219:         let ids = release_package_ids(&workspace.identity, package)?;
220:         if version_is_tagged(tags, &package.id, version) && !ids.iter().any(|id| resumable.contains(id)) {
221:             continue;
222:         }
223:         for id in ids {
224:             entries.push(ReleaseDecisionEntry {
225:                 package: id,
226:                 target_version: version.clone(),
227:                 reasons: vec![ReleaseInclusionReason::UnreleasedVersion],
228:             });
229:         }
230:     }
232:     let mut seen = std::collections::BTreeSet::new();
233:     for selection in selections {
234:         if !seen.insert(selection) {
235:             return Err(GraphError::ReleaseSelectionInvalid {
236:                 package: selection.clone(),
237:                 reason: ReleaseSelectionInvalidReason::Duplicate,
238:             });
239:         }
240:         let Some(package) = workspace_package(workspace, selection) else {
241:             return Err(GraphError::UnknownPackage {
242:                 id: callisto_model::PackageId::Prefixed {
243:                     ecosystem: selection.ecosystem(),
244:                     name: selection.name().to_string(),
245:                 },
246:             });
247:         };
248:         if !has_dispatchable_target(package) {
249:             return Err(GraphError::ReleaseSelectionInvalid {
250:                 package: selection.clone(),
251:                 reason: ReleaseSelectionInvalidReason::NoDispatchableTarget,
252:             });
253:         }
254:         if !entries.iter().any(|entry| &entry.package == selection) {
255:             return Err(GraphError::ReleaseSelectionInvalid {
256:                 package: selection.clone(),
257:                 reason: ReleaseSelectionInvalidReason::NotARelease,
258:             });
259:         }
260:     }
261:     if !selections.is_empty() {
262:         entries = expand_selection(workspace, entries, &seen);
263:     }
264:     if entries.is_empty() {
265:         return Ok(None);
266:     }
267:     ReleaseDecisionV1::new(entries).map(Some).map_err(GraphError::from)
268: }
270: /// Whether `version` of `package` already has a tag in the canonical [`crate::TagIndex`].
271: pub(crate) fn version_is_tagged(
272:     tags: &crate::TagIndex,
273:     package: &callisto_model::PackageId,
274:     version: &Version,
275: ) -> bool {
276:     tag_of_version(tags, package, version).is_some()
277: }
279: pub(crate) fn tag_of_version(
280:     tags: &crate::TagIndex,
281:     package: &callisto_model::PackageId,
282:     version: &Version,
283: ) -> Option<String> {
284:     let rendered = tags.template(package).render(version).to_string();
285:     if tags.is_tag_of(package, &rendered) {
286:         return Some(rendered);
287:     }
288:     tags.last_tag(package)
289:         .filter(|tag| &tag.version == version)
290:         .map(|tag| tag.name.to_string())
291: }
293: /// Entries for every publishable package whose current version is tagged on `source`.
294: ///
295: /// A run that created such a tag may have stopped before pushing it or finishing the release.
296: pub(crate) fn releases_tagged_at<R: callisto_model::CommandRunner, D: DependencyResolver>(
297:     workspace: &Workspace<'_, R, D>,
298:     source: &CommitSha,
299: ) -> Result<Vec<ReleaseDecisionEntry>, GraphError> {
300:     let versions = workspace.base_versions()?;
301:     let tags = workspace.tags()?;
302:     let git = workspace.git_access();
303:     let mut entries = Vec::new();
304:     for package in workspace.graph.packages() {
305:         if !has_dispatchable_target(package) {
306:             continue;
307:         }
308:         let Some(version) = versions.get(&package.id) else {
309:             continue;
310:         };
311:         // Only the tag this run's tag operation would create: one made under an older template is another release's.
312:         let tag = tags.template(&package.id).render(version).to_string();
313:         if !tags.contains_tag(&tag) {
314:             continue;
315:         }
316:         if tags.commit_of(git, &tag)?.as_ref() != Some(source) {
317:             continue;
318:         }
319:         for id in release_package_ids(&workspace.identity, package)? {
320:             entries.push(ReleaseDecisionEntry {
321:                 package: id,
322:                 target_version: version.clone(),
323:                 reasons: vec![ReleaseInclusionReason::UnreleasedVersion],
324:             });
325:         }
326:     }
327:     Ok(entries)
328: }
330: pub(crate) fn has_dispatchable_target(package: &Package) -> bool {
331:     package
332:         .publish_to
333:         .iter()
334:         .any(|target| !matches!(target, callisto_model::PublishTarget::None))
335: }
337: /// The workspace package with this exact release identity.
338: pub(crate) fn workspace_package<'w, R: callisto_model::CommandRunner, D: DependencyResolver>(
339:     workspace: &'w Workspace<'_, R, D>,
340:     id: &ReleasePackageId,
341: ) -> Option<&'w Package> {
342:     // By release identity, not name: a dual-manifest package's npm name can differ from its id.
343:     workspace
344:         .graph
345:         .packages()
346:         .find(|package| release_package_ids(&workspace.identity, package).is_ok_and(|ids| ids.contains(id)))
347: }
349: /// The fixed and linked groups a release package belongs to, per config.
350: fn release_groups_of<R: callisto_model::CommandRunner, D: DependencyResolver>(
351:     workspace: &Workspace<'_, R, D>,
352:     id: &ReleasePackageId,
353: ) -> Vec<(&'static str, callisto_model::GroupName)> {
354:     let Some(package) = workspace_package(workspace, id) else {
355:         return Vec::new();
356:     };
357:     let groups = &workspace.config.groups;
358:     let fixed = groups.fixed_of.iter().map(|(member, group)| ("fixed", member, group));
359:     let linked = groups.linked_of.iter().map(|(member, group)| ("linked", member, group));
360:     // `member` keys are already canonical (`GroupTable::resolve` resolved
361:     // them through `IdentityIndex::resolve`), so exact equality is correct
362:     // here -- `PackageId::matches` would treat a Bare member key as an
363:     // ecosystem wildcard and could match a same-named package elsewhere.
364:     fixed
365:         .chain(linked)
366:         .filter(|(_, member, _)| **member == package.id)
367:         .map(|(kind, _, group)| (kind, group.clone()))
368:         .collect()
369: }
