408: /// The commit's parent and what the commit changed against it, as `(status, path)` pairs. Fails unless `HEAD` is the
409: /// release commit.
410: fn commit_delta<R: CommandRunner, D: DependencyResolver>(
411:     workspace: &Workspace<'_, R, D>,
412:     release_commit: &CommitSha,
413: ) -> Result<(String, Vec<(String, String)>), GraphError> {
414:     let head_args = ["rev-parse", "HEAD"];
415:     let head = git_stdout(workspace.runner, &workspace.root, &head_args)?;
416:     let head =
417:         CommitSha::parse(&head).map_err(|source| command_malformed_output("git", &head_args, source.to_string()))?;
418:     if &head != release_commit {
419:         return Err(GraphError::ReleaseCommitVerificationFailed {
420:             commit: release_commit.clone(),
421:             reason: CommitVerificationFailure::HeadMismatch,
422:         });
423:     }
425:     let parent_ref = format!("{}^", release_commit.as_str());
426:     let parent_args = ["rev-parse", parent_ref.as_str()];
427:     let parent = git_stdout(workspace.runner, &workspace.root, &parent_args)?;
428:     CommitSha::parse(&parent).map_err(|source| command_malformed_output("git", &parent_args, source.to_string()))?;
430:     let diff_tree_args = [
431:         "diff-tree",
432:         "--no-commit-id",
433:         "--name-status",
434:         "-r",
435:         "--no-renames",
436:         parent.as_str(),
437:         release_commit.as_str(),
438:     ];
439:     let changed = git_stdout(workspace.runner, &workspace.root, &diff_tree_args)?;
440:     let changed = parse_name_status(&changed, &diff_tree_args)?;
441:     Ok((parent, changed))
442: }
444: /// The commit has the shape of a version commit: it wrote the decision, consumed a changeset, and touched only the
445: /// paths a version commit may touch.
446: fn require_version_commit_shape<R: CommandRunner, D: DependencyResolver>(
447:     workspace: &Workspace<'_, R, D>,
448:     release_commit: &CommitSha,
449:     changed: &[(String, String)],
450:     decision_path: &str,
451: ) -> Result<(), GraphError> {
452:     let changeset_dir = normalized_git_path(&workspace.config.changesets_dir)?;
454:     // The decision must be freshly authored as part of *this* commit, not a
455:     // stale leftover an earlier release already committed and this one never
456:     // touched -- otherwise a commit that changes nothing real could still
457:     // carry forward a prior, unrelated decision's authority.
458:     let decision_freshly_written = changed
459:         .iter()
460:         .any(|(status, path)| path == decision_path && matches!(status.as_str(), "A" | "M"));
461:     if !decision_freshly_written {
462:         return Err(GraphError::ReleaseCommitVerificationFailed {
463:             commit: release_commit.clone(),
464:             reason: CommitVerificationFailure::DecisionNotWrittenByCommit,
465:         });
466:     }
468:     // A cheap, independent sanity check that this commit is a real version
469:     // application and not just a hand-crafted decision file: some real
470:     // changeset was actually consumed. The decision's own entries, not this
471:     // changeset's content, remain the sole authority verified below.
472:     let consumed_a_changeset = changed
473:         .iter()
474:         .any(|(status, path)| status == "D" && is_changeset_path(path, &changeset_dir));
475:     if !consumed_a_changeset {
476:         return Err(GraphError::ReleaseCommitVerificationFailed {
477:             commit: release_commit.clone(),
478:             reason: CommitVerificationFailure::NoChangesetConsumed,
479:         });
480:     }
482:     // A version commit changes versions and what records them, nothing else. Any other path (build scripts, source,
483:     // a package manager's `.npmrc` or `.cargo/config.toml`, `callisto.toml`, an action) could change what is published
484:     // or where, under the cover of a bot-authored diff.
485:     let changelogs = workspace
486:         .graph
487:         .packages()
488:         .filter_map(|package| package.changelog.as_deref())
489:         .map(normalized_git_path)
490:         .collect::<Result<std::collections::BTreeSet<_>, _>>()?;
491:     for (_, path) in changed {
492:         if !is_version_commit_path(path, decision_path, &changeset_dir, &changelogs) {
493:             return Err(GraphError::ReleaseCommitVerificationFailed {
494:                 commit: release_commit.clone(),
495:                 reason: CommitVerificationFailure::UnexpectedPath { path: path.clone() },
496:             });
497:         }
498:     }
499:     Ok(())
500: }
502: /// The decision file as the release commit holds it. Its own deserializer rejects entries that do not match its digest.
503: fn read_committed_decision<R: CommandRunner, D: DependencyResolver>(
504:     workspace: &Workspace<'_, R, D>,
505:     release_commit: &CommitSha,
506:     decision_path: &std::path::Path,
507:     decision_path_str: &str,
508: ) -> Result<ReleaseDecisionV1, GraphError> {
509:     let decision_source = git_file(
510:         workspace.runner,
511:         &workspace.root,
512:         release_commit.as_str(),
513:         decision_path_str,
514:     )?;
515:     serde_json::from_str(&decision_source).map_err(|error| GraphError::ReleaseDecisionDecode {
516:         path: decision_path.to_path_buf(),
517:         message: error.to_string(),
518:     })
519: }
521: /// Every package the decision claims has its changelog and manifest in the diff with exactly the claimed version, and
522: /// no package the decision does not claim changed version.
523: fn require_manifests_match_decision<R: CommandRunner, D: DependencyResolver>(
524:     workspace: &Workspace<'_, R, D>,
525:     release_commit: &CommitSha,
526:     parent: &str,
