668: /// Whether a version commit may change `path`: a manifest or lockfile anywhere, a package's changelog, the decision
669: /// file, a changeset, or the changesets directory's `pre.json`.
670: fn is_version_commit_path(
671:     path: &str,
672:     decision_path: &str,
673:     changeset_dir: &str,
674:     changelogs: &std::collections::BTreeSet<String>,
675: ) -> bool {
676:     let file_name = path.rsplit('/').next().unwrap_or(path);
677:     let pre_json = if changeset_dir.is_empty() {
678:         "pre.json".to_owned()
679:     } else {
680:         format!("{changeset_dir}/pre.json")
681:     };
682:     path == decision_path
683:         || path == pre_json
684:         || VERSION_MANIFESTS.contains(&file_name)
685:         || VERSION_LOCKFILES.contains(&file_name)
686:         || changelogs.contains(path)
687:         || is_changeset_path(path, changeset_dir)
688: }
690: fn is_changeset_path(path: &str, changeset_dir: &str) -> bool {
691:     let Some(file_name) = path.strip_prefix(changeset_dir).and_then(|path| {
692:         if changeset_dir.is_empty() {
693:             Some(path)
694:         } else {
695:             path.strip_prefix('/')
696:         }
697:     }) else {
698:         return false;
699:     };
701:     !file_name.contains('/') && file_name.ends_with(".md") && file_name != "README.md"
702: }
704: /// Builds a [`GraphError::ReleaseCommand`] (E164) for a git invocation that
705: /// exited non-zero, carrying its real exit status and stderr instead of
706: /// discarding them.
707: pub(super) fn command_non_zero_exit(
708:     program: &str,
709:     args: &[&str],
710:     output: &callisto_model::CommandOutput,
711: ) -> GraphError {
712:     GraphError::ReleaseCommand {
713:         program: program.to_string(),
714:         args: args.iter().map(|s| s.to_string()).collect(),
715:         failure: CommandFailure::NonZeroExit {
716:             exit_code: output.exit_code,
717:             stderr: output.stderr.clone(),
718:         },
719:     }
720: }
722: /// Builds a [`GraphError::ReleaseCommand`] (E164) for a git invocation whose
723: /// output could not be parsed into the shape this module expects.
724: pub(super) fn command_malformed_output(program: &str, args: &[&str], detail: impl Into<String>) -> GraphError {
725:     GraphError::ReleaseCommand {
726:         program: program.to_string(),
727:         args: args.iter().map(|s| s.to_string()).collect(),
728:         failure: CommandFailure::MalformedOutput { detail: detail.into() },
729:     }
730: }
732: fn git_stdout<R: CommandRunner>(runner: &R, root: &std::path::Path, args: &[&str]) -> Result<String, GraphError> {
733:     let output = runner.run_with_timeout("git", args, root, super::release::timeouts::LOCAL_GIT)?;
734:     if !output.success() {
735:         return Err(command_non_zero_exit("git", args, &output));
736:     }
737:     Ok(output.stdout_trimmed().to_string())
738: }
740: fn parse_name_status(output: &str, args: &[&str]) -> Result<Vec<(String, String)>, GraphError> {
741:     output
742:         .lines()
743:         .map(|line| {
744:             let (status, path) = line.split_once('\t').ok_or_else(|| {
745:                 command_malformed_output(
746:                     "git",
747:                     args,
748:                     format!("name-status line missing a tab separator: `{line}`"),
749:                 )
750:             })?;
751:             if !matches!(status, "A" | "M" | "D") || path.is_empty() || path.contains('\0') {
752:                 return Err(command_malformed_output(
753:                     "git",
754:                     args,
755:                     format!("name-status reported an unexpected status/path: `{status}` `{path}`"),
756:                 ));
757:             }
758:             Ok((status.to_string(), path.to_string()))
759:         })
760:         .collect()
761: }
763: fn git_file<R: CommandRunner>(
764:     runner: &R,
765:     root: &std::path::Path,
766:     commit: &str,
767:     path: &str,
768: ) -> Result<String, GraphError> {
769:     let object = format!("{commit}:{path}");
770:     git_stdout(runner, root, &["show", &object])
771: }
773: pub(super) fn normalized_git_path(path: &std::path::Path) -> Result<String, GraphError> {
774:     let path = callisto_model::workspace_relative(path)?;
775:     let path = path.to_string_lossy().into_owned();
776:     if path.contains(['\0', '\n', '\r']) {
777:         return Err(command_malformed_output(
778:             "git",
779:             &["cat-file", "--batch"],
780:             "workspace path contains a forbidden control character",
781:         ));
782:     }
783:     Ok(path)
784: }
