23:     pub fn parse(s: &str) -> Result<Self, globset::Error> {
24:         let (ecosystem, rest) = s
25:             .split_once('/')
26:             .and_then(|(prefix, rest)| Ecosystem::from_prefix(prefix).map(|eco| (Some(eco), rest)))
27:             .unwrap_or((None, s));
28:         let glob = Glob::new(rest)?;
29:         Ok(Self {
30:             raw: s.to_string(),
31:             ecosystem,
32:             matcher: glob.compile_matcher(),
33:         })
34:     }
