2: use globset::{GlobBuilder, GlobSet, GlobSetBuilder};
3: use std::collections::HashMap;
4: use std::path::{Path, PathBuf};
6: use crate::locate::LocateError;
8: /// A manifest's text without a byte-order mark, or `None` when it does not exist. A manifest that exists but
9: /// cannot be read is an error: membership computed from a file we could not read would admit the wrong packages.
10: pub(crate) fn read_root_manifest(path: &Path) -> Result<Option<String>, LocateError> {
11:     match callisto_model::strict_fs::read_optional(path) {
12:         Ok(content) => Ok(content.map(|text| match text.strip_prefix('\u{FEFF}') {
13:             Some(rest) => rest.to_owned(),
14:             None => text,
15:         })),
16:         Err(error) => Err(LocateError::ManifestReadError {
17:             path: path.to_path_buf(),
18:             message: error.to_string(),
19:         }),
20:     }
21: }
23: pub(crate) fn parse_error(path: &Path, message: String) -> LocateError {
24:     LocateError::ManifestParseError {
25:         path: path.to_path_buf(),
26:         message,
27:     }
28: }
30: fn invalid_membership(path: &Path, message: String) -> LocateError {
31:     LocateError::InvalidMembership {
32:         path: path.to_path_buf(),
33:         message,
34:     }
35: }
37: /// Compiles `entries` for the membership `key` of the manifest at `path`; a bad glob is an error, not a skipped entry.
38: fn compile_globs(path: &Path, key: &str, entries: &[String]) -> Result<NegatableGlobSet, LocateError> {
39:     build_globset(entries).map_err(|error| invalid_membership(path, format!("`{key}`: {error}")))
40: }
42: /// A [`GlobSet`] pair implementing npm/pnpm/Yarn-style workspace glob
43: /// negation. `globset`'s `GlobSetBuilder` has no negation concept of its
44: /// own -- a pattern with a leading `!` is just another literal
45: /// positive-match glob to it, so `!packages/excluded` compiles into a glob
46: /// that matches paths literally starting with the character `!`, which
47: /// never matches any real path. That silently no-ops the negation instead
48: /// of excluding anything.
49: ///
50: /// A path is admitted only when it matches at least one `positive` pattern
51: /// and matches none of the `negative` (`!`-stripped) patterns -- mirroring
52: /// how npm/pnpm/Yarn actually resolve workspace globs (later patterns can
53: /// negate earlier ones; a leading `!` excludes). A positive-only pattern
54: /// list behaves exactly as a plain [`GlobSet`] would. An all-negative list
55: /// has an empty positive set, so `is_match` is always `false` -- there is no
56: /// positive baseline for the negation to carve an exclusion out of.
57: pub(crate) struct NegatableGlobSet {
58:     positive: GlobSet,
59:     negative: GlobSet,
60: }
62: impl NegatableGlobSet {
63:     pub(crate) fn is_match(&self, path: &Path) -> bool {
64:         self.positive.is_match(path) && !self.negative.is_match(path)
65:     }
67:     pub(crate) fn empty() -> Self {
68:         NegatableGlobSet {
69:             positive: GlobSet::empty(),
70:             negative: GlobSet::empty(),
71:         }
72:     }
73: }
75: /// `./packages/*` and `packages/*/` name the same directories as `packages/*`, but compiled as written they would
76: /// match no relative path and silently admit nothing.
77: fn normalize_pattern(pattern: &str) -> &str {
78:     let mut rest = pattern;
79:     while let Some(stripped) = rest.strip_prefix("./") {
80:         rest = stripped;
81:     }
82:     if rest.is_empty() && !pattern.is_empty() {
83:         return ".";
84:     }
85:     match rest.trim_end_matches('/') {
86:         "" => rest,
87:         trimmed => trimmed,
88:     }
89: }
91: /// Builds a [`NegatableGlobSet`] from a list of glob strings, matched with
92: /// `literal_separator(true)` semantics (`*` does not cross `/`; `**` does)
93: /// against forward-slash-normalized, workspace-relative paths. An entry
94: /// with a leading `!` is treated as a negative (exclusion) pattern -- see
95: /// [`NegatableGlobSet`].
96: ///
97: /// An entry that fails to compile is an error: skipping it would leave an exclusion or a
98: /// member unapplied and change which packages the workspace admits.
99: pub(crate) fn build_globset(entries: &[String]) -> Result<NegatableGlobSet, globset::Error> {
100:     let mut positive = GlobSetBuilder::new();
101:     let mut negative = GlobSetBuilder::new();
102:     for entry in entries {
103:         let (builder, pattern) = match entry.strip_prefix('!') {
104:             Some(rest) => (&mut negative, rest),
105:             None => (&mut positive, entry.as_str()),
106:         };
107:         builder.add(
108:             GlobBuilder::new(normalize_pattern(pattern))
109:                 .literal_separator(true)
110:                 .build()?,
111:         );
112:     }
113:     Ok(NegatableGlobSet {
114:         positive: positive.build()?,
115:         negative: negative.build()?,
116:     })
117: }

