1: use std::collections::BTreeSet;
2: use std::path::{Path, PathBuf};
4: use callisto_model::{workspace_relative, Ecosystem, PackageId, ProjectRoot};
5: use ignore::WalkBuilder;
7: use crate::parallel::map_in_parallel;
9: use crate::locate::membership;
10: use crate::locate::{find_workspace_root, LocateError, ProjectLocator};
12: pub struct IgnoreWalkLocator {
13:     root: PathBuf,
14:     skip: BTreeSet<&'static str>,
15: }
17: impl IgnoreWalkLocator {
18:     pub fn new(root: &Path) -> Self {
19:         let mut skip = BTreeSet::new();
20:         skip.insert("target");
21:         skip.insert("node_modules");
22:         skip.insert(".git");
23:         skip.insert(".moon");
24:         skip.insert("dist");
26:         let canonical = dunce::canonicalize(root).unwrap_or_else(|_| root.to_path_buf());
27:         IgnoreWalkLocator { root: canonical, skip }
28:     }
30:     pub fn discover(start: &Path, runner: &dyn callisto_model::CommandRunner) -> Result<Self, LocateError> {
31:         let root = find_workspace_root(start, runner)?;
32:         Ok(Self::new(&root))
33:     }
34: }
36: impl ProjectLocator for IgnoreWalkLocator {
37:     fn projects(&self) -> Result<Vec<ProjectRoot>, LocateError> {
38:         Ok(self.projects_and_platform_candidates()?.0)
39:     }
41:     fn projects_and_platform_candidates(&self) -> Result<(Vec<ProjectRoot>, Vec<ProjectRoot>), LocateError> {
42:         let mut results = Vec::new();
43:         let mut platform_candidates = Vec::new();
44:         let cargo_membership = membership::read_cargo_membership(&self.root)?;
45:         let npm_membership = membership::read_npm_membership(&self.root)?;
46:         let python_membership = membership::read_python_membership(&self.root)?;
47:         let mut nested = membership::NestedMemberships::default();
48:         let walker = WalkBuilder::new(&self.root)
49:             .hidden(true)
50:             .git_ignore(true)
51:             // A workspace root below the Git toplevel has no `.git` of its own, but its `.gitignore` must still apply.
52:             .require_git(false)
53:             .parents(false)
54:             .max_depth(Some(32))
55:             // Links are followed only so a package beneath one can be named and rejected; the depth cap bounds a cycle.
56:             .follow_links(true)
57:             .filter_entry({
58:                 let skip = self.skip.clone();
59:                 move |entry| {
60:                     if let Some(name) = entry.file_name().to_str()
61:                         && skip.contains(name)
62:                     {
63:                         return false;
64:                     }
65:                     true
66:                 }
67:             })
68:             .build();
70:         let mut directories = Vec::new();
71:         for entry_res in walker {
72:             let entry = entry_res.map_err(|e| LocateError::Walk {
73:                 path: self.root.clone(),
74:                 message: e.to_string(),
75:             })?;
76:             if entry.path().is_dir() {
77:                 directories.push(entry.into_path());
78:             }
79:         }
81:         // Reading and parsing the manifests is independent per directory, so it runs on several threads. Everything
82:         // that decides, reports or fails stays below, in walk order.
83:         let first_pass = map_in_parallel(&directories, |directory| read_manifests(directory));
85:         for (path, (parsed, failures)) in directories.iter().map(PathBuf::as_path).zip(first_pass) {
86:             let rel = to_workspace_relative(path, &self.root)?;
87:             let is_root = rel == Path::new(".");
88:             let admits = |ecosystem: Ecosystem| match ecosystem {
89:                 Ecosystem::Cargo => cargo_membership.admits(&rel, is_root),
90:                 Ecosystem::Npm => npm_membership.admits(&rel, is_root),
91:                 Ecosystem::Pypi => python_membership.admits(&rel, is_root),
92:                 _ => false,
93:             };
94:             // Own-path check for a *failed* manifest: only a real, explicit members/workspaces
95:             // match counts -- the admit-all fallback (no restriction present, e.g. because this
96:             // very manifest is the one that failed to parse) must not count as membership.
97:             let admits_explicitly = |ecosystem: Ecosystem| match ecosystem {
98:                 Ecosystem::Cargo => cargo_membership.admits_explicitly(&rel, is_root),
99:                 Ecosystem::Npm => npm_membership.admits_explicitly(&rel, is_root),
100:                 Ecosystem::Pypi => python_membership.admits_explicitly(&rel, is_root),
101:                 _ => false,
102:             };
104:             // Explicit only, like `self_admitted` below -- a sibling that's merely admitted by
105:             // the fallback admit-all (no restriction present for that ecosystem) doesn't make
106:             // this directory a real, deliberate workspace member; only a genuine members/
107:             // workspaces match does.
108:             let any_sibling_admitted = parsed
109:                 .iter()
110:                 .any(|(ecosystem, _, identity)| identity.name.is_some() && admits_explicitly(*ecosystem));
112:             for (manifest_path, failure) in failures {
113:                 // Determine which ecosystem this failed manifest belongs to from its
114:                 // file name, to check its own membership independent of any sibling.
115:                 let ecosystem = Ecosystem::CANONICAL.into_iter().find(|eco| {
116:                     eco.canonical_manifest_format()
117:                         .is_some_and(|f| Some(f.file_name()) == manifest_path.file_name().and_then(|n| n.to_str()))
118:                 });
119:                 let self_admitted = ecosystem.is_some_and(admits_explicitly);
120:                 if self_admitted || any_sibling_admitted {
121:                     return Err(match failure {
122:                         ManifestFailure::Unreadable(message) => LocateError::ManifestReadError {
123:                             path: manifest_path,
124:                             message,
125:                         },
126:                         ManifestFailure::Unparseable(message) => LocateError::ManifestParseError {
127:                             path: manifest_path,
128:                             message,
129:                         },
130:                     });
131:                 }
132:                 eprintln!("{}", unparseable_manifest_warning(&manifest_path, &failure));
133:             }
135:             for (ecosystem, content, identity) in parsed {
136:                 let Some(name) = identity.name else {
137:                     continue;
138:                 };
140:                 // A private, versionless package.json that holds an npm workspace (the standard root layout,
141:                 // e.g. `@changesets/cli`, or one below the root) declares a name only to hold `workspaces`; it
142:                 // is never itself a released package, so it never becomes a project.
143:                 if ecosystem == Ecosystem::Npm
144:                     && identity.version.is_none()
145:                     && callisto_manifests::npm_declares_private(&content)
146:                     && (is_root || membership::declares_npm_workspace(path)?)
147:                 {
148:                     continue;
149:                 }
151:                 // A crate with no `version` (an xtask or other internal tool; Cargo reads it as 0.0.0 and cannot
152:                 // publish it) has nothing to version or release, so it is not a package. One that inherits its
153:                 // version from the workspace still is.
154:                 if ecosystem == Ecosystem::Cargo && identity.version.is_none() {
155:                     eprintln!(
156:                         "note: skipping `{}`: it declares no version, so Callisto cannot version or release it",
157:                         rel.display()
158:                     );
159:                     continue;
160:                 }
162:                 let admitted = admits(ecosystem)
163:                     && (is_root
164:                         || membership::nested_workspace_admits(&self.root, &rel, ecosystem, &content, &mut nested)?);
165:                 let id = PackageId::parse(&name).unwrap_or_else(|_| PackageId::Bare(name.clone()));
166:                 let project = ProjectRoot {
167:                     id,
168:                     path: rel.clone(),
169:                     ecosystem,
170:                 };
171:                 if admitted {
172:                     reject_symlinked_package(&self.root, &rel)?;
173:                     results.push(project);
174:                 } else if ecosystem == Ecosystem::Npm && callisto_manifests::npm_role_from_source(&content).is_some() {
175:                     reject_symlinked_package(&self.root, &rel)?;
176:                     platform_candidates.push(project);
177:                 }
178:             }
179:         }
181:         results.sort_by(|a, b| (&a.path, a.ecosystem).cmp(&(&b.path, b.ecosystem)));
182:         platform_candidates.sort_by(|a, b| a.path.cmp(&b.path));
183:         Ok((results, platform_candidates))
184:     }
185: }
187: /// What reading a directory's canonical manifests found: those that parsed, and those that could not be read or parsed.
188: type DirectoryManifests = (
189:     Vec<(Ecosystem, String, callisto_manifests::ManifestIdentity)>,
190:     Vec<(PathBuf, ManifestFailure)>,
191: );
193: /// Reads and parses every canonical manifest present in `path`, so a parse failure can later check whether a *sibling*
194: /// manifest in the directory was admitted, not only its own ecosystem's membership.
195: fn read_manifests(path: &Path) -> DirectoryManifests {
196:     let mut parsed = Vec::new();
197:     let mut failures = Vec::new();
198:     for ecosystem in Ecosystem::CANONICAL {
199:         // Every `Ecosystem::CANONICAL` member has a canonical manifest format by construction -- see its doc comment.
200:         let Some(format) = ecosystem.canonical_manifest_format() else {
201:             continue;
202:         };
203:         let manifest_path = path.join(format.file_name());
204:         let content = match callisto_model::strict_fs::read_optional(&manifest_path) {
205:             Ok(Some(content)) => content,
206:             Ok(None) => continue,
207:             Err(e) => {
208:                 failures.push((manifest_path, ManifestFailure::Unreadable(e.to_string())));
209:                 continue;
210:             }
211:         };
212:         match callisto_manifests::read_identity(format, &content, &manifest_path) {
213:             Ok(identity) => parsed.push((ecosystem, content, identity)),
214:             Err(e) => failures.push((manifest_path, ManifestFailure::Unparseable(e.to_string()))),
215:         }
216:     }
217:     (parsed, failures)
218: }
220: /// Git cannot stage a path beneath a symbolic link, so a package there could be edited on disk but never committed.
221: /// Discovery follows links only so that it can name such a package here instead of silently skipping it.
222: fn reject_symlinked_package(root: &Path, rel: &Path) -> Result<(), LocateError> {
223:     let mut current = root.to_path_buf();
224:     for component in rel.components() {
225:         current.push(component);
226:         let metadata = std::fs::symlink_metadata(&current).map_err(|error| LocateError::Walk {
227:             path: current.clone(),
228:             message: error.to_string(),
229:         })?;
230:         if metadata.file_type().is_symlink() {
231:             return Err(LocateError::SymlinkedPackage {
232:                 path: rel.to_path_buf(),
233:             });
234:         }
235:     }
236:     Ok(())
237: }
239: /// Why a manifest present in a directory could not be turned into an identity.
240: enum ManifestFailure {
241:     Unreadable(String),
242:     Unparseable(String),
243: }
245: /// Warning text for a manifest that fails to read or parse but isn't a workspace member (its own
246: /// ecosystem doesn't admit it, and it shares no directory with an admitted manifest) --
247: /// tested directly, since `eprintln!` output can't be captured from inside discovery.
248: fn unparseable_manifest_warning(path: &Path, failure: &ManifestFailure) -> String {
249:     match failure {
250:         ManifestFailure::Unreadable(message) => {
251:             format!("warning: failed to read manifest `{}`: {message}", path.display())
252:         }
253:         ManifestFailure::Unparseable(message) => {
254:             format!("warning: failed to parse manifest `{}`: {message}", path.display())
255:         }
256:     }
257: }
259: fn to_workspace_relative(path: &Path, root: &Path) -> Result<PathBuf, LocateError> {
260:     if !path.starts_with(root) {
261:         return Err(LocateError::OutsideWorkspaceRoot {
262:             path: path.to_path_buf(),
263:             root: root.to_path_buf(),
264:         });
265:     }
266:     let rel = path
267:         .strip_prefix(root)
268:         .expect("the walk only yields paths under its root");
269:     if rel.as_os_str().is_empty() {
270:         Ok(PathBuf::from("."))
271:     } else {
272:         workspace_relative(rel).map_err(|_e| LocateError::OutsideWorkspaceRoot {
273:             path: path.to_path_buf(),
274:             root: root.to_path_buf(),
275:         })
276:     }
277: }

